(window.PACKS=window.PACKS||[]).push({"id":"secplus","name":"CompTIA Security+ (SY0-701)","short":"Security+","version":1,"lang":"en","sections":{"1":{"en":"General security concepts","fa":"مفاهیم کلی امنیت"},"2":{"en":"Change mgmt & cryptography","fa":"مدیریت تغییر و رمزنگاری"},"3":{"en":"Threat actors & attack surfaces","fa":"مهاجمان و سطوح حمله"},"4":{"en":"Vulnerabilities & IoCs","fa":"آسیب‌پذیری‌ها و نشانه‌های نفوذ"},"5":{"en":"Mitigations & enterprise security","fa":"کاهش ریسک و امنیت سازمانی"},"6":{"en":"Architecture & infrastructure","fa":"معماری و زیرساخت"}},"mcq":[{"id":"secplus:m1","sec":"1","t":"General security concepts","q":"From the Category viewpoint, what is a CCTV camera?","qf":"از نظر دسته‌بندی (Category)، دوربین مداربسته چیست؟","hf":"«Category» یعنی دسته‌بندی کنترل بر اساس ماهیتش: فیزیکی (قفل، دوربین، حصار)، فنی (نرم‌افزار/سخت‌افزار)، مدیریتی (سیاست و رویه)، عملیاتی (کار انسان‌ها). سوال می‌پرسد دوربین مداربسته در کدام دسته است.","o":["Physical","Technical","Managerial","Operational"],"of":["فیزیکی","فنی","مدیریتی","عملیاتی"],"en":"A camera is a physical thing you can touch, so its category is Physical. By type it is both Detective and Deterrent.","fa":"دوربین را می‌شود لمس کرد، پس دسته‌اش Physical است. از نظر نوع، هم Detective است و هم Deterrent."},{"id":"secplus:m2","sec":"1","t":"General security concepts","q":"A security awareness poster on a company wall is which type of control?","qf":"پوستر آگاهی امنیتی روی دیوار شرکت چه نوع کنترلی است؟","hf":"نوع کنترل را مشخص کن: Preventive (جلوگیری فیزیکی/فنی)، Deterrent (بازدارنده: با ترساندن یا هشدار آدم‌ها را منصرف می‌کند)، Detective (کشف)، Corrective (ترمیم). به این فکر کن که پوستر دقیقاً چه کاری با رفتار آدم‌ها می‌کند.","o":["Deterrent","Preventive","Corrective","Detective"],"of":["بازدارنده","پیشگیرانه","اصلاحی","تشخیصی"],"en":"Warning posters discourage bad behavior, so they are Deterrent.","fa":"پوستر هشدار آدم‌ها را از رفتار بد منصرف می‌کند؛ پس Deterrent است."},{"id":"secplus:m3","sec":"1","t":"General security concepts","q":"Restoring data from backup after an attack is what type of control?","qf":"بازگرداندن اطلاعات از Backup بعد از حمله چه نوع کنترلی است؟","hf":"نوع کنترل را مشخص کن: Preventive قبل از حادثه، Detective هنگام کشف، Corrective بعد از حادثه برای برگرداندن وضع به حالت عادی، Directive دستور/سیاست، Compensating جایگزین موقت. اینجا بعد از حمله است.","o":["Corrective","Directive","Detective","Compensating"],"of":["اصلاحی","دستوری","تشخیصی","جبرانی"],"en":"It fixes the situation after the incident, so it is Corrective.","fa":"بعد از حادثه وضعیت را درست می‌کند؛ پس Corrective است."},{"id":"secplus:m4","sec":"1","t":"General security concepts","q":"A ransomware attack mainly violates which part of the CIA triad?","qf":"حمله‌ی باج‌افزار عمدتاً کدام بخش از سه‌گانه‌ی CIA را نقض می‌کند؟","hf":"CIA = محرمانگی (Confidentiality)، یکپارچگی (Integrity)، دسترس‌پذیری (Availability). باج‌افزار فایل‌ها را قفل می‌کند؛ ببین چه چیزی از دست می‌رود.","o":["Availability","Confidentiality","Integrity","Non-repudiation"],"of":["دسترس‌پذیری","محرمانگی","یکپارچگی","عدم انکار"],"en":"Ransomware locks files so they are unavailable.","fa":"باج‌افزار فایل‌ها را قفل می‌کند و در دسترس نیستند؛ پس Availability نقض شده است."},{"id":"secplus:m5","sec":"1","t":"General security concepts","q":"Comparing a downloaded file's hash with the hash published on the website checks which principle?","qf":"مقایسه‌ی Hash فایل دانلودی با Hash اعلام‌شده در سایت، کدام اصل را بررسی می‌کند؟","hf":"Hash یک اثر انگشت از فایل است. اگر فایل حتی یک بیت عوض شود Hash عوض می‌شود. مقایسه‌ی Hash یعنی بررسی اینکه فایل دست‌کاری نشده؛ ببین این به کدام ضلع CIA مربوط است.","o":["Integrity","Availability","Confidentiality","Accounting"],"of":["یکپارچگی","دسترس‌پذیری","محرمانگی","حسابرسی"],"en":"A hash shows whether a file changed, so it checks Integrity.","fa":"Hash نشان می‌دهد فایل تغییر کرده یا نه؛ پس Integrity بررسی می‌شود."},{"id":"secplus:m6","sec":"1","t":"General security concepts","q":"A manager digitally signed a transaction and later cannot say \"that wasn't me\". Which concept is this?","qf":"مدیری تراکنشی را امضای دیجیتال کرده و بعداً نمی‌تواند بگوید «کار من نبود». این کدام مفهوم است؟","hf":"سوال درباره‌ی انکارناپذیری است: کسی که کاری کرده نتواند بعداً بگوید «من نبودم». امضای دیجیتال این را تضمین می‌کند.","o":["Non-repudiation","Authorization","Gap Analysis","Zero Trust"],"of":["عدم انکار","مجوزدهی","تحلیل شکاف","اعتماد صفر"],"en":"Digital signatures provide Non-repudiation.","fa":"امضای دیجیتال قابل انکار نیست؛ پس Non-repudiation است."},{"id":"secplus:m7","sec":"1","t":"General security concepts","q":"In Zero Trust, which component lives in the Data Plane?","qf":"در Zero Trust، کدام جزء در Data Plane قرار دارد؟","hf":"Zero Trust دو بخش دارد: Control Plane (تصمیم‌گیری و سیاست) و Data Plane (جایی که ترافیک واقعی عبور می‌کند و سیاست اجرا می‌شود). ببین کدام جزء کارش «اجرا کردن» است.","o":["Policy Enforcement Point","Policy Engine","Policy Administrator","Gap Analysis"],"of":["نقطه‌ی اجرای سیاست","موتور سیاست","مدیر سیاست","تحلیل شکاف"],"en":"The PEP is in the Data Plane. Policy Engine and Policy Administrator are in the Control Plane.","fa":"PEP در Data Plane است؛ Policy Engine و Policy Administrator در Control Plane هستند."},{"id":"secplus:m8","sec":"1","t":"General security concepts","q":"A fake username is planted in a database and triggers an alert when used. What is it?","qf":"یک نام کاربری جعلی در دیتابیس گذاشته شده که با استفاده از آن هشدار فعال می‌شود. این چیست؟","hf":"تله‌ی فریب: داده‌ی جعلی که هیچ کاربر واقعی سراغش نمی‌رود؛ اگر کسی استفاده‌اش کند یعنی نفوذ شده. خانواده‌ی «Honey...» چند نوع دارد: سیستم تله، فایل تله و نوع سوم برای رکورد/اعتبارنامه‌ی جعلی. کدام با «نام کاربری جعلی در دیتابیس» جور است؟","o":["Honeytoken","Honeypot","Honeynet","Bollard"],"of":["هانی‌توکن (داده‌ی طعمه)","هانی‌پات (سیستم طعمه)","هانی‌نت (شبکه‌ی طعمه)","بولارد (ستون محافظ)"],"en":"Fake data or credentials that trigger an alert are honeytokens.","fa":"داده یا اعتبارنامه‌ی جعلی که با استفاده‌اش هشدار فعال می‌شود Honeytoken است (Honeypot یک سیستم کامل است)."},{"id":"secplus:m9","sec":"1","t":"General security concepts","q":"The badge reader at a door is broken, so a guard is temporarily posted there. Which control type is the guard?","qf":"کارت‌خوان در خراب است و موقتاً یک نگهبان جلوی در گذاشته‌اند. این چه نوع کنترلی است؟","hf":"وقتی کنترل اصلی (کارت‌خوان) خراب شده و کنترل موقت جایگزین می‌شود، به آن کنترل جبرانی می‌گویند. ببین نگهبان کدام نوع است.","o":["Compensating","Preventive","Directive","Corrective"],"of":["جبرانی","پیشگیرانه","دستوری","اصلاحی"],"en":"A temporary control replacing the main one is Compensating.","fa":"نگهبان جای کنترل اصلی (کارت‌خوان) را موقتاً پر می‌کند؛ پس Compensating است."},{"id":"secplus:m10","sec":"1","t":"General security concepts","q":"A user logs in with a password and an SMS code. Which \"A\" of AAA is this?","qf":"کاربر با رمز عبور و کد پیامکی وارد سیستم می‌شود. این کدام «A» از AAA است؟","hf":"AAA = Authentication (تأیید هویت: تو کی هستی؟)، Authorization (مجوز: چه کاری اجازه داری؟)، Accounting (ثبت: چه کردی؟). ورود با رمز + کد پیامکی برای کدام است؟","o":["Authentication","Authorization","Accounting","Availability"],"of":["احراز هویت","مجوزدهی","حسابرسی","دسترس‌پذیری"],"en":"Proving identity is Authentication.","fa":"ثابت کردن هویت با رمز و کد یعنی Authentication."},{"id":"secplus:m11","sec":"1","t":"General security concepts","q":"An Acceptable Use Policy (AUP) is which type of control?","qf":"سیاست استفاده‌ی مجاز (AUP) چه نوع کنترلی است؟","hf":"AUP سند سیاستی است که به کارکنان می‌گوید چه کاری مجاز است و چه کاری نه. نوع کنترلی را مشخص کن که «دستور و راهنمایی» باشد.","o":["Directive","Detective","Corrective","Compensating"],"of":["دستوری","تشخیصی","اصلاحی","جبرانی"],"en":"A policy that tells people how to behave is Directive.","fa":"AUP یک سیاست است که رفتار را تعیین می‌کند؛ پس Directive است."},{"id":"secplus:m12","sec":"1","t":"General security concepts","q":"Which sensor is used to detect body heat?","qf":"کدام حسگر برای تشخیص گرمای بدن استفاده می‌شود؟","hf":"حسگر برای ردیابی حرارت بدن انسان، از نور مرئی استفاده نمی‌کند بلکه تابش گرمایی را می‌گیرد. نوع حسگر را مشخص کن (Microwave, Ultrasonic, Pressure, Infrared).","o":["Infrared","Pressure","Ultrasonic","Microwave"],"of":["مادون قرمز (Infrared)","فشاری","فراصوت","مایکروویو"],"en":"Infrared detects heat.","fa":"Infrared (مادون قرمز) گرما را تشخیص می‌دهد."},{"id":"secplus:m13","sec":"2","t":"Change management & cryptography","q":"Which group reviews and approves IT changes?","qf":"کدام گروه تغییرات IT را بررسی و تأیید می‌کند؟","hf":"Change Management یعنی هر تغییر در IT قبل از اجرا باید بررسی شود. گروهی که این تغییرها را تأیید می‌کند چه نام دارد؟","o":["CAB","SOC","CA","RA"],"of":["CAB (هیئت مشورتی تغییر)","SOC (مرکز عملیات امنیت)","CA (مرجع صدور گواهی)","RA (مرجع تأیید هویت)"],"en":"The Change Advisory Board (CAB) approves changes. A CA issues certificates and an RA verifies identity.","fa":"CAB تغییرات را بررسی و تأیید می‌کند. CA گواهی صادر می‌کند و RA هویت را تأیید می‌کند."},{"id":"secplus:m14","sec":"2","t":"Change management & cryptography","q":"If a patch breaks the system, which document says how to return to the previous state?","qf":"اگر یک وصله سیستم را خراب کند، کدام سند می‌گوید چطور به حالت قبل برگردیم؟","hf":"قبل از هر تغییر، سندی آماده می‌شود که در صورت شکست بگوید چطور برگردیم. اسم آن سند را مشخص کن.","o":["Backout Plan","SOP","Impact Analysis","CSR"],"of":["نقشه‌ی برگشت (Backout Plan)","دستورالعمل استاندارد (SOP)","تحلیل اثر","درخواست گواهی (CSR)"],"en":"The Backout Plan is the rollback plan.","fa":"Backout Plan نقشه‌ی برگشت به حالت قبل است."},{"id":"secplus:m15","sec":"2","t":"Change management & cryptography","q":"What type of encryption is AES?","qf":"AES چه نوع رمزنگاری‌ای است؟","hf":"رمزنگاری دو نوع دارد: Symmetric (یک کلید مشترک برای قفل و باز کردن، سریع) و Asymmetric (جفت کلید عمومی/خصوصی، کندتر). AES کدام است؟","o":["Symmetric","Asymmetric","Hashing","Steganography"],"of":["متقارن","نامتقارن","هش‌کردن","پنهان‌نگاری"],"en":"AES uses one shared key, so it is symmetric.","fa":"AES از یک کلید مشترک استفاده می‌کند؛ پس متقارن (Symmetric) است."},{"id":"secplus:m16","sec":"2","t":"Change management & cryptography","q":"What is the best way to store user passwords in a database?","qf":"بهترین روش ذخیره‌ی رمز عبور کاربران در دیتابیس چیست؟","hf":"رمز عبور را هرگز ساده ذخیره نکن. هش یک‌طرفه است و Salt یک مقدار تصادفی که به هر رمز اضافه می‌شود. بهترین روش چیست؟","o":["Salted hash","Plain text","AES encryption","Data masking"],"of":["هش همراه با Salt","متن ساده","رمزنگاری AES","پوشاندن داده"],"en":"Hashing is one-way and a salt stops rainbow tables. AES is reversible, so it is wrong for passwords.","fa":"Hash یک‌طرفه است و Salt جلوی Rainbow Table را می‌گیرد. AES قابل برگشت است و برای رمز عبور مناسب نیست."},{"id":"secplus:m17","sec":"2","t":"Change management & cryptography","q":"What does a browser use to check in real time whether a certificate was revoked?","qf":"مرورگر برای بررسی لحظه‌ای باطل شدن یک گواهی از چه استفاده می‌کند؟","hf":"گواهی ممکن است باطل (Revoked) شود. مرورگر باید فوراً از CA بپرسد. CRL یک لیست بزرگ است که دوره‌ای دانلود می‌شود، ولی پروتکل «پرسش لحظه‌ای» چیست؟","o":["OCSP","CRL","CSR","X.509"],"of":["OCSP (بررسی لحظه‌ای)","CRL (فهرست ابطال)","CSR (درخواست گواهی)","X.509 (قالب گواهی)"],"en":"OCSP checks in real time. A CRL is a list that must be downloaded.","fa":"OCSP بررسی لحظه‌ای است. CRL یک فهرست است که باید دانلود شود."},{"id":"secplus:m18","sec":"2","t":"Change management & cryptography","q":"One certificate works for mail.example.com, shop.example.com and all other subdomains. What type is it?","qf":"یک گواهی برای mail.example.com، shop.example.com و بقیه‌ی زیردامنه‌ها کار می‌کند. این چه نوع گواهی است؟","hf":"یک گواهی برای همه‌ی ساب‌دامین‌ها (mail.، shop.، ...) با علامت * مثل *.example.com. نوع این گواهی را مشخص کن.","o":["Wildcard","Self-signed","Root","Intermediate"],"of":["Wildcard (همه‌ی زیردامنه‌ها)","خودامضا","ریشه (Root)","میانی (Intermediate)"],"en":"A wildcard certificate (*.example.com) covers all subdomains.","fa":"گواهی Wildcard (*.example.com) همه‌ی زیردامنه‌ها را پوشش می‌دهد."},{"id":"secplus:m19","sec":"2","t":"Change management & cryptography","q":"Showing only the last 4 digits of a credit card on an invoice is which method?","qf":"نمایش فقط ۴ رقم آخر کارت بانکی در فاکتور کدام روش است؟","hf":"Masking یعنی بخشی از داده را پنهان نشان دادن (مثل ****1234) بدون تغییر داده‌ی اصلی، در مقابل Tokenization (جایگزینی با توکن) و Encryption (رمز). نام روش را مشخص کن.","o":["Data Masking","Tokenization","Hashing","Steganography"],"of":["پوشاندن داده (Data Masking)","توکن‌سازی","هش‌کردن","پنهان‌نگاری"],"en":"Hiding part of the data is Data Masking. Tokenization replaces the whole value with a token.","fa":"پوشاندن بخشی از داده Data Masking است (Tokenization کل داده را با ژتون عوض می‌کند)."},{"id":"secplus:m20","sec":"2","t":"Change management & cryptography","q":"What is the chip on a laptop motherboard that stores BitLocker keys?","qf":"تراشه‌ی روی مادربرد لپ‌تاپ که کلیدهای BitLocker را نگه می‌دارد چیست؟","hf":"یک تراشه‌ی سخت‌افزاری روی مادربرد که کلیدها را امن نگه می‌دارد و در BitLocker استفاده می‌شود. نامش را مشخص کن (HSM یک دستگاه جدا/سازمانی است، TPM روی لپ‌تاپ).","o":["TPM","HSM","KMS","CA"],"of":["TPM (تراشه‌ی داخل دستگاه)","HSM (دستگاه سخت‌افزاری مدیریت کلید)","KMS (سیستم مدیریت کلید)","CA (مرجع صدور گواهی)"],"en":"A TPM is a chip inside the device. An HSM is a separate enterprise appliance.","fa":"TPM تراشه‌ی داخل دستگاه است. HSM دستگاه جداگانه‌ی سازمانی است."},{"id":"secplus:m21","sec":"2","t":"Change management & cryptography","q":"In a digital signature, the sender encrypts the hash with which key?","qf":"در امضای دیجیتال، فرستنده Hash را با کدام کلید رمز می‌کند؟","hf":"در امضای دیجیتال هش پیام با یک کلید رمز می‌شود تا هویت فرستنده ثابت شود. فقط خود فرستنده این کلید را دارد؛ کدام کلید (خصوصی یا عمومی، فرستنده یا گیرنده)؟","o":["Sender's private key","Receiver's public key","Receiver's private key","Sender's public key"],"of":["کلید خصوصی فرستنده","کلید عمومی گیرنده","کلید خصوصی گیرنده","کلید عمومی فرستنده"],"en":"The sender signs with their own private key and the receiver verifies with the sender's public key.","fa":"فرستنده با کلید خصوصی خودش امضا می‌کند و گیرنده با کلید عمومی فرستنده بررسی می‌کند."},{"id":"secplus:m22","sec":"2","t":"Change management & cryptography","q":"In PKI, who verifies the identity of a certificate requester?","qf":"در PKI چه کسی هویت درخواست‌کننده‌ی گواهی را تأیید می‌کند؟","hf":"در PKI چند نقش داریم: CA (صادرکننده‌ی گواهی)، RA (ثبت‌نام و تأیید هویت درخواست‌کننده)، CRL/OCSP (ابطال). کدام یکی هویت را تأیید می‌کند؟","o":["RA","OCSP","TPM","CAB"],"of":["RA (مرجع تأیید هویت)","OCSP","TPM","CAB"],"en":"The RA verifies identity, then the CA issues the certificate.","fa":"RA هویت را تأیید می‌کند و بعد CA گواهی را صادر می‌کند."},{"id":"secplus:m23","sec":"2","t":"Change management & cryptography","q":"A salt primarily protects against which attack?","qf":"Salt در درجه‌ی اول جلوی کدام حمله را می‌گیرد؟","hf":"Salt مقدار تصادفی افزوده به رمز قبل از هش است. ببین این در برابر کدام حمله (جدول هش‌های از پیش محاسبه‌شده) محافظت می‌کند.","o":["Rainbow table","Phishing","DDoS","On-path"],"of":["Rainbow Table (جدول هش‌های آماده)","فیشینگ","DDoS","On-Path (واسط‌گیری)"],"en":"A salt makes precomputed hash tables useless.","fa":"Salt باعث می‌شود جدول‌های آماده‌ی Hash (Rainbow Table) بی‌فایده شوند."},{"id":"secplus:m24","sec":"2","t":"Change management & cryptography","q":"Hiding a secret message inside an image file is called:","qf":"پنهان کردن یک پیام مخفی داخل فایل عکس چه نام دارد؟","hf":"پنهان کردن پیام در یک فایل عادی (تصویر/صوت) به‌طوری که کسی نفهمد پیامی هست. این با رمزنگاری فرق دارد که پیام را «ناخوانا» می‌کند ولی پنهان نمی‌کند.","o":["Steganography","Tokenization","Hashing","Salting"],"of":["پنهان‌نگاری (Steganography)","توکن‌سازی","هش‌کردن","Salt زدن"],"en":"Hiding a message in another file is steganography.","fa":"پنهان کردن پیام داخل فایل دیگر Steganography است."},{"id":"secplus:m25","sec":"3","t":"Threat actors & attack surfaces","q":"A very advanced, well-funded group backed by a government for espionage is:","qf":"گروهی بسیار پیشرفته و پرپول که با حمایت یک دولت برای جاسوسی حمله می‌کند چیست؟","hf":"بازیگر تهدید با پشتوانه‌ی دولتی، بودجه‌ی بالا، هدف جاسوسی و مهارت پیشرفته. بازیگران دیگر: Hacktivist (ایدئولوژی)، Insider (داخلی)، Organized Crime (پول)، Script Kiddie (کم‌مهارت). کدام با «حمایت دولت» جور است؟","o":["Nation-State","Script Kiddie","Hacktivist","Insider"],"of":["مهاجم دولتی (Nation-State)","اسکریپت‌کیدی (مبتدی)","هکتیویست (هکر ایدئولوژیک)","نفوذی داخلی (Insider)"],"en":"Advanced, well-funded and state-backed is a Nation-State actor (often an APT).","fa":"پیشرفته، پرپول و با حمایت دولت یعنی Nation-State (معمولاً APT)."},{"id":"secplus:m26","sec":"3","t":"Threat actors & attack surfaces","q":"What is the main motivation of a hacktivist?","qf":"انگیزه‌ی اصلی Hacktivist چیست؟","hf":"Hacktivist ترکیب Hacker + Activist است. ببین انگیزه‌ی اصلی او چیست (پول، جاسوسی، انتقام، یا ...).","o":["Ideology / political cause","Financial gain","Personal revenge","Espionage for a government"],"of":["ایدئولوژی / هدف سیاسی","سود مالی","انتقام شخصی","جاسوسی برای یک دولت"],"en":"Hacktivists attack for ideology or protest, not money.","fa":"Hacktivist برای ایدئولوژی و اعتراض حمله می‌کند، نه پول."},{"id":"secplus:m27","sec":"3","t":"Threat actors & attack surfaces","q":"You receive an SMS with a fake bank link. What attack is this?","qf":"پیامکی با لینک جعلی بانک دریافت کرده‌اید. این چه حمله‌ای است؟","hf":"پیامک جعلی با لینک بانکی. فیشینگ انواعی دارد بر اساس کانال: ایمیل، تلفن، پیامک. کدام برای پیامک است؟","o":["Smishing","Vishing","Typosquatting","Pretexting"],"of":["Smishing (فیشینگ پیامکی)","Vishing (فیشینگ تلفنی)","Typosquatting (دامنه‌ی غلط‌تایپی)","Pretexting (داستان‌سازی)"],"en":"SMS + phishing = smishing. Vishing is by phone call.","fa":"SMS + Phishing = Smishing. (Vishing تلفنی است.)"},{"id":"secplus:m28","sec":"3","t":"Threat actors & attack surfaces","q":"An attacker registers the domain micros0ft.com. What is this?","qf":"مهاجم دامنه‌ی micros0ft.com را ثبت کرده است. این چیست؟","hf":"ثبت دامنه‌ای که با یک اشتباه تایپی شبیه برند واقعی است (mikrosoft، micros0ft). اسم این حمله را مشخص کن.","o":["Typosquatting","Rogue AP","Steganography","DNS Poisoning"],"of":["Typosquatting (دامنه‌ی غلط‌تایپی)","Rogue AP (نقطه‌ی دسترسی جعلی)","پنهان‌نگاری","DNS Poisoning (مسموم‌سازی DNS)"],"en":"A look-alike domain with a typo is typosquatting.","fa":"دامنه‌ای شبیه دامنه‌ی اصلی با غلط تایپی یعنی Typosquatting."},{"id":"secplus:m29","sec":"3","t":"Threat actors & attack surfaces","q":"Which group of protocols helps prevent email spoofing?","qf":"کدام گروه پروتکل‌ها جلوی جعل ایمیل را می‌گیرد؟","hf":"جعل ایمیل را با اعتبارسنجی فرستنده متوقف می‌کنند. سه رکورد DNS برای این کار وجود دارد؛ سوال گروه آن‌ها را می‌خواهد.","o":["SPF, DKIM, DMARC","TLS, IPSec, SSH","CRL, OCSP, CSR","AES, RSA, SHA"],"of":["SPF، DKIM، DMARC (احراز هویت ایمیل)","TLS، IPSec، SSH (رمزنگاری انتقال)","CRL، OCSP، CSR (گواهی‌ها)","AES، RSA، SHA (الگوریتم‌های رمزنگاری)"],"en":"SPF, DKIM and DMARC are email authentication protocols.","fa":"SPF، DKIM و DMARC پروتکل‌های احراز هویت ایمیل هستند."},{"id":"secplus:m30","sec":"3","t":"Threat actors & attack surfaces","q":"The SolarWinds attack is an example of which attack vector?","qf":"حمله‌ی SolarWinds نمونه‌ای از کدام مسیر حمله است؟","hf":"بردار حمله یعنی راه ورود. حمله از طریق نرم‌افزار آلوده‌ی یک تأمین‌کننده‌ی مورد اعتماد (به‌روزرسانی رسمی آلوده) به کدام بردار می‌خورد؟","o":["Supply Chain","Removable Media","Vishing","Open Port"],"of":["زنجیره‌ی تأمین (Supply Chain)","رسانه‌ی قابل‌حمل","Vishing (فیشینگ تلفنی)","پورت باز"],"en":"A trusted vendor's software update was infected, which is a supply chain attack.","fa":"آپدیت نرم‌افزار یک فروشنده‌ی معتبر آلوده شد؛ پس Supply Chain است."},{"id":"secplus:m31","sec":"3","t":"Threat actors & attack surfaces","q":"An employee stores work files in a personal Dropbox account. What is this?","qf":"کارمندی فایل‌های کاری را در Dropbox شخصی‌اش ذخیره می‌کند. این چیست؟","hf":"استفاده از ابزار یا سرویس خارج از اطلاع/تأیید واحد IT. نام این پدیده را مشخص کن.","o":["Shadow IT","Malicious insider","APT","Honeyfile"],"of":["Shadow IT (فناوری سایه)","نفوذی داخلی بدخواه","APT (تهدید پیشرفته‌ی مداوم)","Honeyfile (فایل طعمه)"],"en":"Using a service without IT approval is Shadow IT, not necessarily malicious.","fa":"استفاده از سرویس بدون اجازه‌ی IT یعنی Shadow IT؛ لزوماً بدخواهانه نیست."},{"id":"secplus:m32","sec":"3","t":"Threat actors & attack surfaces","q":"A Windows XP machine in a factory has no patches and cannot be replaced now. What is the best action?","qf":"یک سیستم Windows XP در کارخانه وصله ندارد و فعلاً نمی‌شود عوضش کرد. بهترین کار چیست؟","hf":"سیستم قدیمی که پچ ندارد و قابل تعویض هم نیست. وقتی نمی‌شود خود سیستم را اصلاح کرد، باید راه‌هایی پیدا کنی که خطر را از بیرون کم کند. گزینه‌ها را از نظر «واقع‌بینانه و ایمن بودن» مقایسه کن.","o":["Segment it and use virtual patching with IPS","Leave it as is","Connect it directly to the internet","Disable the firewall"],"of":["آن را جدا (Segment) کنید و با IPS وصله‌ی مجازی بزنید","همین‌طور بگذارید","مستقیم به اینترنت وصل کنید","فایروال را غیرفعال کنید"],"en":"Segmentation and virtual patching with an IPS are compensating controls.","fa":"وقتی وصله نیست، Segmentation و Virtual Patching با IPS کنترل‌های جبرانی هستند."},{"id":"secplus:m33","sec":"3","t":"Threat actors & attack surfaces","q":"A fake Wi-Fi network with the company's name is set up to steal traffic. What is it?","qf":"یک Wi-Fi جعلی هم‌نام Wi-Fi شرکت راه افتاده تا ترافیک را بدزدد. این چیست؟","hf":"نقطه‌ی دسترسی بی‌سیمِ فریبنده با اسم شبکه‌ی شرکت برای شنود ترافیک. اسم این نوع دستگاه/حمله را مشخص کن (Evil Twin هم ممکن است نام‌اش باشد ولی گزینه‌ها را نگاه کن).","o":["Rogue Access Point","Honeynet","VLAN","Bollard"],"of":["نقطه‌ی دسترسی جعلی (Rogue AP)","Honeynet (شبکه‌ی طعمه)","VLAN","بولارد (ستون محافظ)"],"en":"A fake access point impersonating the company Wi-Fi is a Rogue Access Point.","fa":"نقطه‌ی دسترسی جعلی هم‌نام Wi-Fi شرکت Rogue Access Point است."},{"id":"secplus:m34","sec":"3","t":"Threat actors & attack surfaces","q":"A caller says \"I'm from IT, I need your password to fix a problem\". Which technique is this?","qf":"کسی تلفنی می‌گوید «از واحد IT هستم و برای رفع مشکل رمزتان را لازم دارم». این کدام تکنیک است؟","hf":"مهاجم یک داستان/بهانه‌ی جعلی (از IT هستم) می‌سازد تا اطلاعات بگیرد. این تکنیک مهندسی اجتماعی چه نام دارد؟","o":["Pretexting","Typosquatting","Tokenization","Defacement"],"of":["Pretexting (داستان‌سازی)","Typosquatting (دامنه‌ی غلط‌تایپی)","Tokenization (توکن‌سازی)","Defacement (تغییر ظاهر سایت)"],"en":"Building a believable story is pretexting.","fa":"ساختن داستان باورپذیر («از IT هستم») Pretexting است."},{"id":"secplus:m35","sec":"3","t":"Threat actors & attack surfaces","q":"An infected USB drive labeled \"Confidential Salaries\" is left in the parking lot. Which technical control helps most?","qf":"یک USB آلوده با برچسب «حقوق محرمانه» در پارکینگ رها شده است. کدام کنترل فنی بیشترین کمک را می‌کند؟","hf":"فلش آلوده با برچسب وسوسه‌انگیز: حمله‌ی «فیزیکی». کنترل فنی (نه آموزش) را مشخص کن که جلوی اجرای خودکار یا استفاده از USB ناشناس را بگیرد.","o":["Disable autorun and block unauthorized USB devices","Enable autorun","Use WPA3","Install a wildcard certificate"],"of":["Autorun را غیرفعال و USBهای غیرمجاز را مسدود کنید","Autorun را فعال کنید","از WPA3 استفاده کنید","گواهی Wildcard نصب کنید"],"en":"Disabling autorun and blocking unauthorized USB devices stops the malware from running.","fa":"غیرفعال کردن Autorun و بلاک USBهای غیرمجاز جلوی اجرای بدافزار را می‌گیرد."},{"id":"secplus:m36","sec":"3","t":"Threat actors & attack surfaces","q":"A teenager attacks sites with ready-made tools and no deep knowledge. What type of attacker is this?","qf":"نوجوانی با ابزار آماده و بدون دانش عمیق به سایت‌ها حمله می‌کند. او چه نوع مهاجمی است؟","hf":"مهاجم کم‌مهارتی که از ابزار آماده استفاده می‌کند. نوع بازیگر تهدید را مشخص کن.","o":["Unskilled Attacker (Script Kiddie)","Nation-State","Organized Crime","Insider"],"of":["مهاجم کم‌مهارت (Script Kiddie)","مهاجم دولتی","جرم سازمان‌یافته","نفوذی داخلی"],"en":"Ready-made tools and no deep knowledge is a script kiddie.","fa":"کسی که با ابزار آماده و بدون دانش عمیق حمله می‌کند Script Kiddie است."},{"id":"secplus:m37","sec":"4","t":"Vulnerabilities & IoCs","q":"An attacker enters ' OR 1=1 -- in a login field. What attack is this?","qf":"مهاجم در فیلد لاگین ' OR 1=1 -- وارد می‌کند. این چه حمله‌ای است؟","hf":"رشته‌ی ' OR 1=1 -- یک تزریق به کوئری پایگاه داده است تا شرط ورود همیشه درست شود. نام این حمله را مشخص کن.","o":["SQL Injection","XSS","Buffer Overflow","Directory Traversal"],"of":["SQL Injection (تزریق SQL)","XSS","Buffer Overflow (سرریز بافر)","Directory Traversal (پیمایش پوشه)"],"en":"It makes the SQL condition always true, which is SQL injection.","fa":"' OR 1=1 -- شرط SQL را همیشه درست می‌کند؛ پس SQL Injection است."},{"id":"secplus:m38","sec":"4","t":"Vulnerabilities & IoCs","q":"A URL request containing ../../../etc/passwd indicates which attack?","qf":"درخواست ../../../etc/passwd در URL نشانه‌ی کدام حمله است؟","hf":"../ یعنی یک پوشه بالاتر رفتن. مهاجم با آن از پوشه‌ی وب بیرون می‌زند و به فایل‌های سیستم می‌رسد. نام حمله را مشخص کن.","o":["Directory Traversal","Command Injection","DNS Poisoning","Collision"],"of":["Directory Traversal (پیمایش پوشه)","Command Injection (تزریق دستور)","DNS Poisoning (مسموم‌سازی DNS)","Collision (برخورد هش)"],"en":"../ means going up a folder, which is directory traversal.","fa":"../ یعنی رفتن به پوشه‌ی بالاتر؛ پس Directory Traversal است."},{"id":"secplus:m39","sec":"4","t":"Vulnerabilities & IoCs","q":"Malware that replicates itself across the network without user action is a:","qf":"بدافزاری که بدون دخالت کاربر در شبکه خودش را تکثیر می‌کند چیست؟","hf":"بدافزاری که بدون نیاز به عمل کاربر و بدون میزبان، خودش در شبکه تکثیر می‌شود. (ویروس نیاز به اجرای فایل دارد، تروجان خودش را مفید جا می‌زند.)","o":["Worm","Trojan","Virus","Logic Bomb"],"of":["کرم (Worm)","تروجان","ویروس","بمب منطقی"],"en":"A worm self-replicates. A virus needs a user action.","fa":"Worm بدون دخالت کاربر خودش را تکثیر می‌کند. Virus به اقدام کاربر نیاز دارد."},{"id":"secplus:m40","sec":"4","t":"Vulnerabilities & IoCs","q":"You downloaded a free PDF reader that actually installed a backdoor. What is it?","qf":"یک PDF Reader رایگان دانلود کرده‌اید که در واقع Backdoor نصب کرد. این چیست؟","hf":"نرم‌افزار ظاهراً مفید که پشت صحنه کار مخرب (در پشتی) نصب می‌کند. اسم بدافزار را مشخص کن.","o":["Trojan","Worm","Rootkit","Keylogger"],"of":["تروجان (Trojan)","کرم","روت‌کیت","کی‌لاگر"],"en":"Looks legitimate but secretly harmful: a Trojan.","fa":"ظاهر سالم با کار مخفی مخرب یعنی Trojan."},{"id":"secplus:m41","sec":"4","t":"Vulnerabilities & IoCs","q":"An attacker tries the password Welcome1 on all 500 company accounts. What is this?","qf":"مهاجم رمز Welcome1 را روی همه‌ی ۵۰۰ حساب شرکت امتحان می‌کند. این چیست؟","hf":"Password Spraying یعنی یک رمز رایج را روی تعداد زیادی حساب امتحان کردن (برعکس Brute Force که رمزهای زیاد روی یک حساب است). این سناریو کدام است؟","o":["Password Spraying","Brute Force","Credential Stuffing","Birthday Attack"],"of":["Password Spraying (پاشیدن یک رمز)","Brute Force (حدس فراگیر)","Credential Stuffing (استفاده از اعتبارنامه‌های لورفته)","Birthday Attack (حمله‌ی تولد)"],"en":"One password across many accounts is password spraying.","fa":"یک رمز روی حساب‌های زیاد یعنی Password Spraying."},{"id":"secplus:m42","sec":"4","t":"Vulnerabilities & IoCs","q":"An attacker forces a connection to use TLS 1.0 instead of TLS 1.3. What is this?","qf":"مهاجم ارتباط را مجبور می‌کند به‌جای TLS 1.3 از TLS 1.0 استفاده کند. این چیست؟","hf":"مهاجم پروتکل امن جدید را مجبور می‌کند به نسخه‌ی قدیمی و ضعیف برگردد. نام این حمله را مشخص کن.","o":["Downgrade","Collision","On-Path","Replay"],"of":["Downgrade (تنزل نسخه)","Collision (برخورد هش)","On-Path (واسط‌گیری)","Replay (بازپخش)"],"en":"Forcing an older, weaker version is a downgrade attack.","fa":"مجبور کردن به نسخه‌ی قدیمی‌تر و ضعیف‌تر یعنی Downgrade."},{"id":"secplus:m43","sec":"4","t":"Vulnerabilities & IoCs","q":"An attacker moves from inside a virtual machine to the host system. What is this?","qf":"مهاجم از داخل یک ماشین مجازی به سیستم میزبان دسترسی پیدا می‌کند. این چیست؟","hf":"فرار از ماشین مجازی (Guest) و رسیدن به سیستم میزبان (Host). نام این حمله را مشخص کن.","o":["VM Escape","Resource Reuse","Sideloading","Rooting"],"of":["VM Escape (فرار از ماشین مجازی)","Resource Reuse (استفاده‌ی مجدد منبع)","Sideloading (نصب خارج از فروشگاه رسمی)","Rooting (روت‌کردن)"],"en":"Breaking out of a VM to reach the host is VM escape.","fa":"بیرون آمدن از VM و رسیدن به میزبان یعنی VM Escape."},{"id":"secplus:m44","sec":"4","t":"Vulnerabilities & IoCs","q":"A vulnerability unknown to the vendor with no patch available is called:","qf":"آسیب‌پذیری‌ای که سازنده از آن خبر ندارد و وصله‌ای برایش نیست چیست؟","hf":"آسیب‌پذیری‌ای که سازنده خبر ندارد و پچی برایش نیست؛ «روز صفر». نامش را مشخص کن.","o":["Zero-Day","Legacy","End-of-Life","Misconfiguration"],"of":["Zero-Day (روز صفر)","Legacy (قدیمی)","End-of-Life (پایان پشتیبانی)","Misconfiguration (پیکربندی اشتباه)"],"en":"Unknown to the vendor and unpatched is a zero-day.","fa":"ناشناخته برای سازنده و بدون وصله یعنی Zero-Day."},{"id":"secplus:m45","sec":"4","t":"Vulnerabilities & IoCs","q":"An employee planted code that wipes all data if their name is removed from payroll. What is it?","qf":"کارمندی کدی گذاشته که اگر اسمش از لیست حقوق حذف شد، همه‌ی داده‌ها پاک شوند. این چیست؟","hf":"کدی که در سیستم کاشته می‌شود و با یک شرط خاص (مثلاً حذف شدن نام کارمند) فعال می‌شود. نام آن را مشخص کن.","o":["Logic Bomb","Rootkit","Ransomware","Worm"],"of":["بمب منطقی (Logic Bomb)","روت‌کیت","باج‌افزار","کرم"],"en":"Code triggered by a condition is a logic bomb.","fa":"کدی که با یک شرط فعال می‌شود Logic Bomb است."},{"id":"secplus:m46","sec":"4","t":"Vulnerabilities & IoCs","q":"Which of these is NOT an indicator of compromise (IoC)?","qf":"کدام مورد IoC (نشانه‌ی نفوذ) نیست؟","hf":"IoC نشانه‌ی نفوذ است (ترافیک غیرعادی، فایل ناشناس، لاگین از مکان عجیب). سوال می‌خواهد موردی را پیدا کنی که «نشانه‌ی نفوذ نیست» و فعالیت عادی است.","o":["Scheduled monthly patch installation","Login at 3 AM from a foreign country","Deleted logs","Large outbound traffic to an unknown IP"],"of":["نصب برنامه‌ریزی‌شده‌ی وصله‌ی ماهانه","ورود ساعت ۳ صبح از یک کشور خارجی","پاک شدن لاگ‌ها","ترافیک خروجی زیاد به یک IP ناشناس"],"en":"A scheduled patch is normal, safe activity.","fa":"نصب وصله طبق برنامه‌ی کاری عادی و امن است، نه نشانه‌ی نفوذ."},{"id":"secplus:m47","sec":"4","t":"Vulnerabilities & IoCs","q":"Two simultaneous withdrawal requests both pass the balance check. Which vulnerability is this?","qf":"دو درخواست برداشت هم‌زمان ارسال می‌شود و هر دو از بررسی موجودی رد می‌شوند. این کدام آسیب‌پذیری است؟","hf":"دو درخواست هم‌زمان قبل از به‌روزرسانی موجودی هر دو چک را رد می‌کنند (Time-of-Check to Time-of-Use). نام آسیب‌پذیری را مشخص کن.","o":["Race Condition (TOC/TOU)","Buffer Overflow","XSS","VM Escape"],"of":["Race Condition (شرایط رقابتی)","Buffer Overflow (سرریز بافر)","XSS","VM Escape (فرار از ماشین مجازی)"],"en":"Exploiting the gap between check and use is a race condition.","fa":"سوءاستفاده از فاصله‌ی بین بررسی و استفاده یعنی Race Condition (TOC/TOU)."},{"id":"secplus:m48","sec":"4","t":"Vulnerabilities & IoCs","q":"An S3 bucket was left publicly accessible. What kind of vulnerability is this?","qf":"یک S3 Bucket به‌طور عمومی قابل دسترسی رها شده است. این کدام نوع آسیب‌پذیری است؟","hf":"باکت ذخیره‌سازی ابری که عمومی شده. این از «ضعف در کد» نیست، از تنظیم اشتباه است. نوع آسیب‌پذیری را مشخص کن.","o":["Cloud misconfiguration","Firmware malware","Zero-Day","Race condition"],"of":["پیکربندی اشتباه ابری","بدافزار Firmware","Zero-Day (روز صفر)","Race Condition (شرایط رقابتی)"],"en":"A cloud resource accidentally public is a cloud misconfiguration.","fa":"فضای ابری که اشتباهاً عمومی مانده یعنی پیکربندی اشتباه ابری."},{"id":"secplus:m49","sec":"4","t":"Vulnerabilities & IoCs","q":"A script placed in a website comment steals other users' sessions. What is it?","qf":"اسکریپتی در کامنت یک سایت گذاشته شده که Session بقیه‌ی کاربران را می‌دزدد. این چیست؟","hf":"اسکریپت در یک صفحه‌ی وب تزریق می‌شود و در مرورگر قربانی اجرا می‌شود. نام حمله (سه‌حرفی) را مشخص کن.","o":["XSS","SQL Injection","Command Injection","DDoS"],"of":["XSS (اسکریپت‌نویسی بین‌سایتی)","SQL Injection (تزریق SQL)","Command Injection (تزریق دستور)","DDoS (انکار سرویس توزیع‌شده)"],"en":"A script that runs in other users' browsers is cross-site scripting.","fa":"اسکریپتی که در مرورگر کاربران دیگر اجرا می‌شود XSS است."},{"id":"secplus:m50","sec":"5","t":"Mitigations & enterprise security","q":"Which system detects an attack and also stops it?","qf":"کدام سیستم حمله را تشخیص می‌دهد و جلویش را هم می‌گیرد؟","hf":"IDS فقط تشخیص می‌دهد (Detective) و IPS تشخیص و مسدود می‌کند (Preventive). کدام هر دو کار را می‌کند؟","o":["IPS","IDS","SIEM","NetFlow"],"of":["IPS (سیستم پیشگیری از نفوذ)","IDS (سیستم تشخیص نفوذ)","SIEM","NetFlow"],"en":"An IPS blocks. An IDS only alerts.","fa":"IPS جلوی حمله را هم می‌گیرد. IDS فقط هشدار می‌دهد."},{"id":"secplus:m51","sec":"5","t":"Mitigations & enterprise security","q":"Which method is NOT effective for destroying SSD data?","qf":"کدام روش برای پاک کردن داده‌ی SSD مؤثر نیست؟","hf":"حافظه‌ی SSD با HDD فرق دارد؛ روش‌هایی که برای دیسک مغناطیسی کار می‌کنند ممکن است برای SSD جواب ندهند. سوال گزینه‌ای را می‌خواهد که «بی‌اثر» است.","o":["Degaussing","Cryptographic erasure","Shredding","Incineration"],"of":["Degaussing (پاک‌سازی مغناطیسی)","پاک‌سازی رمزنگاری‌شده","خردکردن","سوزاندن"],"en":"Degaussing is magnetic, and SSDs are not magnetic.","fa":"Degaussing مغناطیسی است و SSD مغناطیسی نیست."},{"id":"secplus:m52","sec":"5","t":"Mitigations & enterprise security","q":"In a hospital only approved software is allowed to run. What is this?","qf":"در یک بیمارستان فقط نرم‌افزارهای تأییدشده اجازه‌ی اجرا دارند. این چیست؟","hf":"فقط برنامه‌های تأییدشده اجازه‌ی اجرا دارند و بقیه مسدودند. اسم این روش (Allow List / Deny List) را مشخص کن.","o":["Application Allow List","Antivirus","Sandbox","DLP"],"of":["فهرست مجاز برنامه‌ها (Allow List)","آنتی‌ویروس","Sandbox (محیط ایزوله)","DLP (جلوگیری از نشت داده)"],"en":"Only approved software may run: an application allow list.","fa":"فقط اجرای نرم‌افزارهای تأییدشده یعنی Application Allow List."},{"id":"secplus:m53","sec":"5","t":"Mitigations & enterprise security","q":"Port 3389 belongs to which service?","qf":"پورت 3389 مربوط به کدام سرویس است؟","hf":"شماره‌ی پورت‌ها را حفظ کن: 22 SSH، 23 Telnet، 25 SMTP، 53 DNS، 80 HTTP، 443 HTTPS، 3389 RDP، 445 SMB. ببین 3389 مال کدام است.","o":["RDP","SMB","FTP","HTTPS"],"of":["RDP (دسکتاپ از راه دور)","SMB (اشتراک فایل)","FTP (انتقال فایل)","HTTPS"],"en":"Port 3389 is RDP.","fa":"پورت 3389 مال RDP است."},{"id":"secplus:m54","sec":"5","t":"Mitigations & enterprise security","q":"Isolating each container in a cloud environment independently is called:","qf":"جداسازی هر Container در محیط ابری به‌صورت مستقل چه نام دارد؟","hf":"تقسیم شبکه تا سطح کانتینر یا workload جداگانه؛ ریزتر از Segmentation معمولی. اسم آن را مشخص کن.","o":["Micro-segmentation","Air Gap","DMZ","VLAN"],"of":["Micro-segmentation (ریزتقسیم‌بندی)","Air Gap (جدایی فیزیکی)","DMZ (منطقه‌ی غیرنظامی)","VLAN"],"en":"Isolation at the container level is micro-segmentation.","fa":"جداسازی در سطح هر Container یعنی Micro-segmentation."},{"id":"secplus:m55","sec":"5","t":"Mitigations & enterprise security","q":"An admin gets high-level access only when needed and for 2 hours. What is this?","qf":"ادمین فقط وقتی لازم است و برای ۲ ساعت دسترسی سطح بالا می‌گیرد. این چیست؟","hf":"دسترسی بالا فقط برای مدت کوتاه و فقط وقتی لازم است (نه دائمی). اسم این مفهوم/روش را مشخص کن.","o":["Just-In-Time Access","RBAC","Allow List","ACL"],"of":["Just-In-Time Access (دسترسی به‌موقع)","RBAC (کنترل دسترسی مبتنی بر نقش)","فهرست مجاز","ACL (فهرست کنترل دسترسی)"],"en":"Temporary access only when needed is just-in-time access.","fa":"دسترسی موقت فقط موقع نیاز یعنی Just-In-Time Access."},{"id":"secplus:m56","sec":"5","t":"Mitigations & enterprise security","q":"A suspicious file is run in an isolated environment to observe its behavior. What is the environment?","qf":"یک فایل مشکوک را برای دیدن رفتارش در محیطی ایزوله اجرا می‌کنیم. این محیط چیست؟","hf":"اجرای فایل مشکوک در محیط ایزوله که به سیستم اصلی آسیب نزند. نام آن محیط را مشخص کن.","o":["Sandbox","DMZ","Honeynet","VLAN"],"of":["Sandbox (محیط ایزوله)","DMZ","Honeynet (شبکه‌ی طعمه)","VLAN"],"en":"An isolated environment for running suspicious files is a sandbox.","fa":"محیط ایزوله برای اجرای فایل مشکوک Sandbox است."},{"id":"secplus:m57","sec":"5","t":"Mitigations & enterprise security","q":"Server settings slowly move away from the standard configuration. What is this problem called?","qf":"تنظیمات سرورها کم‌کم از پیکربندی استاندارد فاصله گرفته‌اند. اسم این مشکل چیست؟","hf":"تنظیمات سرورها به‌مرور از حالت استاندارد (Baseline) دور می‌شوند. نام این پدیده را مشخص کن.","o":["Drift","Downgrade","Shadow IT","Collision"],"of":["Drift (انحراف از پیکربندی)","Downgrade (تنزل نسخه)","Shadow IT (فناوری سایه)","Collision (برخورد هش)"],"en":"Gradual deviation from the baseline is configuration drift.","fa":"فاصله گرفتن تدریجی از Baseline یعنی Drift."},{"id":"secplus:m58","sec":"5","t":"Mitigations & enterprise security","q":"Closing port 445 on devices would have stopped the spread of which famous malware?","qf":"بستن پورت 445 روی دستگاه‌ها جلوی گسترش کدام بدافزار مشهور را می‌گرفت؟","hf":"پورت 445 مربوط به SMB است؛ بدافزاری که از ضعف SMB (EternalBlue) در سال ۲۰۱۷ گسترده شد. نام آن را مشخص کن.","o":["WannaCry","Stuxnet","Emotet","LoJax"],"of":["WannaCry","Stuxnet","Emotet","LoJax"],"en":"WannaCry spread via SMB (port 445) using EternalBlue.","fa":"WannaCry از SMB (پورت 445) و آسیب‌پذیری EternalBlue سوءاستفاده کرد."},{"id":"secplus:m59","sec":"5","t":"Mitigations & enterprise security","q":"Internet-facing web and email servers are normally placed in which area?","qf":"سرورهای وب و ایمیل که رو به اینترنت هستند معمولاً در کدام بخش قرار می‌گیرند؟","hf":"منطقه‌ی بین اینترنت و شبکه‌ی داخلی برای سرورهای عمومی (وب/ایمیل). نام این منطقه‌ی امنیتی را مشخص کن.","o":["DMZ","Air-gapped network","Guest VLAN","Sandbox"],"of":["DMZ (منطقه‌ی غیرنظامی)","شبکه‌ی Air-gapped (جداشده‌ی فیزیکی)","VLAN مهمان","Sandbox"],"en":"Internet-facing servers go in the DMZ to separate them from the internal network.","fa":"سرورهای رو به اینترنت در DMZ قرار می‌گیرند تا از شبکه‌ی داخلی جدا باشند."},{"id":"secplus:m60","sec":"5","t":"Mitigations & enterprise security","q":"Which tool collects logs from all systems and correlates events?","qf":"کدام ابزار لاگ‌های همه‌ی سیستم‌ها را جمع می‌کند و رویدادها را به هم ربط می‌دهد (Correlate)؟","hf":"ابزاری که لاگ‌ها را از همه‌ی سیستم‌ها جمع می‌کند، با هم تطبیق می‌دهد و هشدار می‌دهد. نام آن (چهار حرف) را مشخص کن.","o":["SIEM","TPM","WAF","MDM"],"of":["SIEM (جمع‌آوری و ربط‌دهی لاگ)","TPM","WAF","MDM (مدیریت دستگاه موبایل)"],"en":"A SIEM collects and correlates logs.","fa":"SIEM لاگ‌ها را جمع و Correlate می‌کند."},{"id":"secplus:m61","sec":"5","t":"Mitigations & enterprise security","q":"Recording exactly who accessed an evidence hard drive and when is called:","qf":"ثبت دقیق اینکه چه کسی و کی به یک هارد دیسک مدرک دسترسی داشته چه نام دارد؟","hf":"در تحقیقات دیجیتال باید ثابت شود مدرک دست‌کاری نشده؛ ثبت دقیق چه کسی، کی و چرا به مدرک دسترسی داشته. نام این فرآیند چیست؟","o":["Chain of Custody","Gap Analysis","Baseline","Backout Plan"],"of":["Chain of Custody (زنجیره‌ی نگهداری مدرک)","Gap Analysis (تحلیل شکاف)","Baseline (خط پایه)","Backout Plan (نقشه‌ی برگشت)"],"en":"Tracking who handled evidence and when is the chain of custody.","fa":"ثبت اینکه چه کسی و کی به مدرک دسترسی داشته Chain of Custody است."},{"id":"secplus:m62","sec":"6","t":"Cloud & shared responsibility","q":"In the cloud shared responsibility model, which task is always the customer's responsibility?","qf":"در مدل مسئولیت مشترک Cloud، کدام کار همیشه بر عهده‌ی مشتری است؟","hf":"مدل مسئولیت مشترک ابری: ارائه‌دهنده امنیت «خودِ ابر» (سخت‌افزار، مرکز داده) را دارد و مشتری امنیت «آنچه داخل ابر می‌گذارد» (داده، دسترسی‌ها). ببین کدام وظیفه همیشه با مشتری است.","o":["Encrypting data and configuring access controls on the data they store","Physical security of the provider's data center","Patching the provider's hypervisor","Maintaining power and cooling for the data center"],"of":["رمزنگاری داده و پیکربندی کنترل دسترسی برای داده‌ای که ذخیره می‌کند","امنیت فیزیکی دیتاسنتر ارائه‌دهنده","وصله‌کردن Hypervisor ارائه‌دهنده","تأمین برق و خنک‌سازی دیتاسنتر"],"en":"The provider secures the physical facility and the platform. The customer owns their data, its encryption (in transit and at rest), access controls and workload configuration.","fa":"ارائه‌دهنده امنیت فیزیکی و پلتفرم را دارد. مشتری مسئول داده، رمزنگاری (in transit و at rest)، کنترل دسترسی و پیکربندی workloadهاست."},{"id":"secplus:m63","sec":"6","t":"Cloud & shared responsibility","q":"Which is the MOST common cause of cloud data exposure?","qf":"شایع‌ترین دلیل افشای داده در Cloud کدام است؟","hf":"آمار نشان می‌دهد بیشتر نشت‌های ابری از حمله‌ی پیچیده نیست. دنبال شایع‌ترین علت بگرد.","o":["Misconfiguration, such as an open S3 bucket or an overly permissive IAM role","Theft of servers from the provider's data center","Fiber cuts between availability zones","Expired hardware warranties"],"of":["Misconfiguration (پیکربندی اشتباه)، مثل S3 Bucket باز یا نقش IAM بیش از حد مجاز","سرقت سرورها از دیتاسنتر ارائه‌دهنده","قطع فیبر بین Availability Zoneها","تمام شدن گارانتی سخت‌افزار"],"en":"Misconfiguration is the number one cloud risk. Public buckets and over-permissive IAM roles are the textbook examples.","fa":"misconfiguration ریسک شماره یک cloud است. bucket عمومی و نقش IAM بیش از حد مجاز مثال‌های کلاسیک‌اند."},{"id":"secplus:m64","sec":"6","t":"Cloud & shared responsibility","q":"An organization runs an AWS EC2 instance (IaaS). Which control is the customer's job?","qf":"سازمانی یک ماشین EC2 در AWS (IaaS) اجرا می‌کند. کدام کنترل کار مشتری است؟","hf":"در IaaS ارائه‌دهنده سخت‌افزار و مجازی‌ساز را دارد؛ سیستم‌عامل و برنامه‌ها با مشتری است. ببین کار مشتری چیست.","o":["OS hardening and patching with a vulnerability management program","Physical access to the host server","Replacing failed host disks","Patching the hypervisor"],"of":["Hardening و پچ‌کردن سیستم‌عامل با برنامه‌ی مدیریت آسیب‌پذیری","دسترسی فیزیکی به سرور میزبان","تعویض دیسک‌های خراب میزبان","پچ‌کردن Hypervisor"],"en":"EC2 is a virtual machine. OS-level hardening and patching are the customer's responsibility, just like an on-prem server.","fa":"EC2 یک ماشین مجازی است؛ hardening و patch کردن سیستم‌عامل با مشتری است، مثل سرور on-prem."},{"id":"secplus:m65","sec":"6","t":"Cloud & shared responsibility","q":"An S3 bucket mainly requires which type of security control from the customer?","qf":"یک S3 Bucket بیشتر چه نوع کنترل امنیتی از مشتری می‌خواهد؟","hf":"S3 یک سرویس ذخیره‌ی شیء است. کنترلی را مشخص کن که مشتری باید برای آن تنظیم کند (دسترسی و ثبت)، نه سخت‌افزار.","o":["Strict bucket policies and logging","OS-level patching","Antivirus on the bucket","Installing a host firewall"],"of":["Bucket Policy سخت‌گیرانه و Logging","پچ‌کردن سطح سیستم‌عامل","آنتی‌ویروس روی Bucket","نصب فایروال میزبان"],"en":"S3 is configuration-driven. Strict bucket policies, appropriate to the data sensitivity, plus logging are the key controls.","fa":"S3 مبتنی بر پیکربندی است؛ bucket policy سخت‌گیرانه و logging مهم‌ترین کنترل‌هاست."},{"id":"secplus:m66","sec":"6","t":"Cloud & shared responsibility","q":"A company moves a system to a cloud provider and assumes the provider now carries all liability for a privacy breach. What is wrong with this assumption?","qf":"شرکتی سیستمی را به Cloud منتقل می‌کند و فرض می‌کند ارائه‌دهنده کل مسئولیت قانونی نشت اطلاعات را می‌پذیرد. اشکال این فرض چیست؟","hf":"انتقال ریسک (Risk Transfer) یعنی بخشی از کار یا هزینه به دیگری منتقل می‌شود، ولی مسئولیت نهایی داده و قانون با سازمان می‌ماند. ببین فرض اشتباه کجاست.","o":["Risk transfer shifts responsibility but not the organization's accountability to its customers","Cloud providers always take full legal liability","Accountability transfers only for SaaS","Accountability is eliminated once a contract is signed"],"of":["Risk Transfer مسئولیت را منتقل می‌کند ولی پاسخ‌گویی (Accountability) سازمان در برابر مشتریانش می‌ماند","ارائه‌دهنده‌های Cloud همیشه کل مسئولیت قانونی را می‌پذیرند","پاسخ‌گویی فقط در SaaS منتقل می‌شود","با امضای قرارداد پاسخ‌گویی از بین می‌رود"],"en":"You can transfer responsibility for running components, but you cannot transfer accountability to your customers and regulators.","fa":"می‌توان مسئولیت اجرا را منتقل کرد ولی پاسخ‌گویی (accountability) در برابر مشتری و قانون با خود سازمان می‌ماند."},{"id":"secplus:m67","sec":"6","t":"Cloud & shared responsibility","q":"An enterprise connects on-prem to AWS and wants a dedicated, private link instead of the internet. Which option fits?","qf":"سازمانی On-Prem را به AWS وصل می‌کند و به‌جای اینترنت یک لینک اختصاصی و خصوصی می‌خواهد. کدام گزینه مناسب است؟","hf":"لینک اختصاصی خصوصی از دیتاسنتر به ابر، بدون اینترنت عمومی. AWS اسم محصول مخصوص این کار را دارد (در Azure ExpressRoute است). گزینه‌ها را نگاه کن.","o":["Direct Connect","Site-to-site VPN over the public internet","TLS 1.3","A CDN"],"of":["Direct Connect","VPN سایت‌به‌سایت روی اینترنت عمومی","TLS 1.3","CDN"],"en":"Direct Connect is a dedicated physical connection (contracts, often via providers like Equinix). A VPN is easier to deploy but rides the internet and can be slower.","fa":"Direct Connect اتصال اختصاصی فیزیکی است. VPN راحت‌تر است ولی روی اینترنت می‌رود و ممکن است کندتر باشد."},{"id":"secplus:m68","sec":"6","t":"Cloud & shared responsibility","q":"A company uses AWS, Azure and on-prem. What should be standardized across all of them?","qf":"شرکتی از AWS، Azure و On-Prem استفاده می‌کند. چه چیزی باید در همه‌ی آن‌ها یکسان شود؟","hf":"در چندابری/ترکیبی، ابزار هر ارائه‌دهنده فرق دارد؛ چیزی که باید یکسان باشد سیاست‌ها و خط‌مبناها است نه ابزار مخصوص هر ابر.","o":["Governance, policies and baseline configurations","The cloud vendor's proprietary features","The password of each admin","Only the backup schedule"],"of":["Governance، سیاست‌ها و پیکربندی‌های Baseline","قابلیت‌های اختصاصی هر فروشنده‌ی Cloud","رمز عبور هر ادمین","فقط زمان‌بندی پشتیبان‌گیری"],"en":"Consistent policy enforcement and baselines across the whole estate keep a uniform security level in hybrid and multi-cloud designs.","fa":"اعمال سیاست و baseline یکسان در کل زیرساخت hybrid و multi-cloud باعث یکنواخت ماندن سطح امنیت می‌شود."},{"id":"secplus:m69","sec":"6","t":"Cloud & shared responsibility","q":"Autoscaling is enabled and a DDoS hits a cloud app with no rate limiting. What is a likely consequence?","qf":"Autoscaling روشن است و حمله‌ی DDoS به یک اپ Cloud بدون Rate Limiting می‌خورد. نتیجه‌ی محتمل چیست؟","hf":"Autoscaling منابع را با بار بالا می‌برد. بدون محدودیت نرخ (Rate Limiting) حمله‌ی DDoS هم باعث افزایش منابع می‌شود. پیامد مالی را مشخص کن.","o":["A very large cloud bill because the app scales to absorb malicious traffic","The cloud provider automatically refunds all charges","The app goes offline immediately","Nothing, since scaling is free"],"of":["صورت‌حساب خیلی بزرگ Cloud، چون اپ برای جذب ترافیک مخرب scale می‌شود","ارائه‌دهنده‌ی Cloud همه‌ی هزینه‌ها را خودکار برمی‌گرداند","اپ فوراً آفلاین می‌شود","هیچ، چون scale شدن رایگان است"],"en":"Cost is variable. Without rate limiting or protections, malicious traffic triggers scaling and you pay for it.","fa":"هزینه متغیر است؛ بدون rate limiting ترافیک مخرب باعث scale شدن و پرداخت هزینه‌ی زیاد می‌شود."},{"id":"secplus:m70","sec":"6","t":"Serverless, IaC & microservices","q":"Which workload is LEAST suited to a serverless function such as AWS Lambda?","qf":"کدام بار کاری کمتر از همه برای یک تابع Serverless مثل AWS Lambda مناسب است؟","hf":"Serverless (مثل Lambda) توابع کوتاه‌مدت و رویدادمحور است. مناسب نیست برای کارهایی که طولانی، پیوسته و پرمنبع‌اند؛ ببین کدام گزینه چنین است.","o":["A multi-hour batch data transformation job","Sending a notification after a trigger event","Processing a single payment transaction","Reacting to a file upload to S3"],"of":["یک کار دسته‌ای چندساعته‌ی تبدیل داده","ارسال اعلان بعد از یک رویداد","پردازش یک تراکنش پرداخت","واکنش به آپلود فایل در S3"],"en":"Lambda runs short-lived code (max 15 minutes). Long-running data jobs belong on something like AWS Glue.","fa":"Lambda برای کد کوتاه‌مدت (حداکثر ۱۵ دقیقه) است؛ کارهای طولانی داده مثل Glue مناسب‌ترند."},{"id":"secplus:m71","sec":"6","t":"Serverless, IaC & microservices","q":"Which is a key SECURITY benefit of serverless?","qf":"کدام مورد مزیت امنیتی کلیدی Serverless است؟","hf":"در Serverless سیستم‌عامل و سرور را ارائه‌دهنده مدیریت می‌کند. فایده‌ی امنیتی را مشخص کن (کم شدن چیست؟).","o":["Reduced attack surface, with no OS or network to manage","The customer patches the underlying OS","Unlimited execution time","Full visibility into the provider's host"],"of":["سطح حمله‌ی کمتر، چون OS یا شبکه‌ای برای مدیریت نیست","مشتری سیستم‌عامل زیرین را پچ می‌کند","زمان اجرای نامحدود","دید کامل به میزبان ارائه‌دهنده"],"en":"The provider manages OS, patching and infrastructure, so the customer's attack surface is smaller.","fa":"ارائه‌دهنده OS و patch را مدیریت می‌کند، پس attack surface مشتری کمتر است."},{"id":"secplus:m72","sec":"6","t":"Serverless, IaC & microservices","q":"Which is a main risk of serverless architectures?","qf":"کدام مورد ریسک اصلی معماری Serverless است؟","hf":"چون توابع کوتاه‌عمر هستند، مانیتورینگ سنتی (Agent روی سرور) ممکن نیست. ریسک اصلی را مشخص کن.","o":["Limited visibility into short-lived executions and reliance on the provider's patching","No ability to scale","Mandatory on-prem hardware","Inability to react to events"],"of":["دید محدود به اجراهای کوتاه‌مدت و وابستگی به پچ‌کردن ارائه‌دهنده","ناتوانی در مقیاس‌دهی","نیاز اجباری به سخت‌افزار On-Prem","ناتوانی در واکنش به رویدادها"],"en":"Executions are ephemeral, so logging and observability must be built deliberately. You also depend on the provider (third-party risk).","fa":"اجراها زودگذرند، پس باید logging و observability بسازید؛ وابستگی به ارائه‌دهنده هم ریسک شخص ثالث است."},{"id":"secplus:m73","sec":"6","t":"Serverless, IaC & microservices","q":"What is a \"cold start\" in serverless?","qf":"«Cold Start» در Serverless چیست؟","hf":"Cold Start: تابع مدتی استفاده نشده و باید دوباره آماده شود. ببین کدام تعریف مشکل را درست توصیف می‌کند (تأخیر، نه خرابی).","o":["Added latency when a function runs after a period with no warm instance","A failed deployment","A firewall rule that blocks all traffic","Encryption key rotation"],"of":["تأخیر اضافی وقتی تابع بعد از مدتی بی‌کاری اجرا می‌شود و instance گرم وجود ندارد","یک استقرار ناموفق","قانون فایروال که همه‌ی ترافیک را مسدود می‌کند","چرخش کلید رمزنگاری"],"en":"With no recent invocations there is no warm instance, so the first request is delayed while the environment starts.","fa":"اگر مدتی فراخوانی نباشد instance گرم وجود ندارد و اولین درخواست تأخیر دارد."},{"id":"secplus:m74","sec":"6","t":"Serverless, IaC & microservices","q":"Which is a benefit of Infrastructure as Code (IaC)?","qf":"کدام مورد مزیت Infrastructure as Code (IaC) است؟","hf":"IaC یعنی زیرساخت را با کد تعریف و مدیریت کردن (نه کلیک دستی). فایده‌ی اصلی‌اش را مشخص کن (تکرارپذیری، نسخه‌بندی).","o":["Consistent, repeatable deployments with version control and rollback","Removal of the need for any security review","Manual configuration of each server","Guaranteed zero misconfigurations"],"of":["استقرار یکسان و تکرارپذیر با Version Control و Rollback","حذف نیاز به هر بازبینی امنیتی","پیکربندی دستی هر سرور","تضمین صفر Misconfiguration"],"en":"IaC templates make 1000 VMs identical, are version-controlled, and can be rolled back.","fa":"IaC استقرار یکسان و تکرارپذیر، version control و rollback می‌دهد."},{"id":"secplus:m75","sec":"6","t":"Serverless, IaC & microservices","q":"Which is a common IaC security risk?","qf":"کدام مورد ریسک امنیتی رایج IaC است؟","hf":"چون IaC کد است، مشکلات کدنویسی را هم دارد. ببین ریسک رایج چیست (چیزی که نباید داخل ریپازیتوری باشد).","o":["Hard-coded secrets in code repositories and insecure template defaults","Servers that are too consistent","Too much version control","Using declarative language"],"of":["Secretهای Hard-code شده در Repository و پیش‌فرض‌های ناامن Template","سرورهایی که بیش از حد یکسان‌اند","Version Control بیش از حد","استفاده از زبان Declarative"],"en":"Scan IaC code for secrets and make sure reusable templates are secure by default.","fa":"secret در repository و template ناامن خطر اصلی IaC است؛ کد IaC را اسکن کنید."},{"id":"secplus:m76","sec":"6","t":"Serverless, IaC & microservices","q":"Terraform is best described as:","qf":"Terraform بهتر از همه چطور توصیف می‌شود؟","hf":"Terraform ابزار IaC شرکت HashiCorp است. «Declarative» یعنی شما حالت نهایی را می‌گویید نه مراحل را، و «Cloud-agnostic» یعنی به یک ابر خاص وابسته نیست.","o":["A declarative, cloud-agnostic IaC tool that can also deploy on-premise","A firewall appliance","A SIEM platform","An AWS-only storage service"],"of":["ابزار IaC که Declarative و مستقل از Cloud است و روی On-Prem هم استقرار می‌دهد","یک دستگاه فایروال","یک پلتفرم SIEM","یک سرویس ذخیره‌سازی مخصوص AWS"],"en":"Terraform scripts declare the desired configuration, work across clouds, and also support on-prem.","fa":"Terraform ابزار declarative و مستقل از cloud است و on-prem را هم پشتیبانی می‌کند."},{"id":"secplus:m77","sec":"6","t":"Serverless, IaC & microservices","q":"In a microservices design, services communicate with each other mainly through:","qf":"در طراحی Microservices، سرویس‌ها عمدتاً از چه راهی با هم ارتباط می‌گیرند؟","hf":"میکروسرویس‌ها یک برنامه‌ی بزرگ را به سرویس‌های کوچک تقسیم می‌کنند. ببین از چه راهی با هم حرف می‌زنند.","o":["APIs","Shared physical memory","Direct database writes into each other","Email"],"of":["API","حافظه‌ی فیزیکی مشترک","نوشتن مستقیم در دیتابیس یکدیگر","ایمیل"],"en":"Independent, loosely coupled services interact through APIs and API contracts.","fa":"سرویس‌ها از طریق API و API contract با هم ارتباط دارند."},{"id":"secplus:m78","sec":"6","t":"Serverless, IaC & microservices","q":"What is a primary security downside of microservices?","qf":"ضعف امنیتی اصلی Microservices چیست؟","hf":"میکروسرویس یعنی تعداد زیادی سرویس و نقطه‌ی ارتباط. ببین ضعف اصلی امنیتی چیست.","o":["A larger attack surface because of many API endpoints and weaker centralized control","Lack of fault isolation","Inability to version services","They require a single monolithic database"],"of":["سطح حمله‌ی بزرگ‌تر به‌خاطر Endpointهای API زیاد و کنترل متمرکز ضعیف‌تر","نبود جداسازی خطا","ناتوانی در نسخه‌بندی سرویس‌ها","نیاز به یک دیتابیس یکپارچه‌ی واحد"],"en":"More endpoints means more entry points and more chances for API abuse.","fa":"endpointهای زیاد یعنی attack surface بزرگ‌تر و سوءاستفاده‌ی بیشتر از API."},{"id":"secplus:m79","sec":"6","t":"On-prem, SDN & architecture","q":"Which is a classic benefit of on-premises infrastructure?","qf":"کدام مورد مزیت کلاسیک زیرساخت On-Premises است؟","hf":"On-prem یعنی تجهیزات در سازمان خودت. ببین مزیت کلاسیکش چیست (کنترل، حاکمیت داده).","o":["Full control over systems and data, and strict data residency","Low upfront cost","No need for IT staff","Instant elastic scaling"],"of":["کنترل کامل روی سیستم‌ها و داده، و Data Residency سخت‌گیرانه","هزینه‌ی اولیه‌ی کم","نیاز نداشتن به کادر IT","مقیاس‌دهی فوری و کشسان"],"en":"On-prem gives physical control and clear data residency for compliance. The downsides are capital cost, maintenance and staffing.","fa":"on-prem کنترل کامل و data residency دارد؛ ولی هزینه‌ی اولیه، نگهداری و نیروی IT می‌خواهد."},{"id":"secplus:m80","sec":"6","t":"On-prem, SDN & architecture","q":"Which scenario is a typical on-prem example?","qf":"کدام سناریو مثال معمول On-Prem است؟","hf":"مثال معمول On-prem را مشخص کن: همه‌چیز داخل ساختمان/دیتاسنتر خود شرکت (مثل Active Directory محلی).","o":["An in-house data center running Active Directory for internal authentication","A Lambda function reacting to an upload","A SaaS CRM subscription","A CDN edge location"],"of":["یک دیتاسنتر داخلی که Active Directory را برای احراز هویت داخلی اجرا می‌کند","تابع Lambda که به یک آپلود واکنش نشان می‌دهد","اشتراک CRM به‌صورت SaaS","یک نقطه‌ی لبه‌ی CDN"],"en":"Many organizations still run domain services on-prem.","fa":"بسیاری از سازمان‌ها هنوز Active Directory را on-prem اجرا می‌کنند."},{"id":"secplus:m81","sec":"6","t":"On-prem, SDN & architecture","q":"What does Software-Defined Networking (SDN) do?","qf":"شبکه‌ی نرم‌افزارمحور (SDN) چه می‌کند؟","hf":"SDN شبکه را با نرم‌افزار کنترل می‌کند. دو لایه: Control Plane (تصمیم) و Data Plane (ارسال). ببین کار SDN چیست.","o":["Separates the control plane from the data plane for centralized, programmable control","Replaces all firewalls","Encrypts all traffic by default","Eliminates the need for routing"],"of":["صفحه‌ی کنترل را از صفحه‌ی داده جدا می‌کند تا کنترل متمرکز و برنامه‌پذیر داشته باشیم","همه‌ی فایروال‌ها را جایگزین می‌کند","همه‌ی ترافیک را به‌طور پیش‌فرض رمزنگاری می‌کند","نیاز به مسیریابی را از بین می‌برد"],"en":"SDN centralizes control and enables dynamic traffic management and granular segmentation.","fa":"SDN صفحه‌ی کنترل را از صفحه‌ی داده جدا می‌کند و کنترل متمرکز و برنامه‌پذیر می‌دهد."},{"id":"secplus:m82","sec":"6","t":"On-prem, SDN & architecture","q":"What is a main risk of SDN?","qf":"ریسک اصلی SDN چیست؟","hf":"در SDN یک کنترلر مرکزی همه‌چیز را هدایت می‌کند. ریسک اصلی چنین مرکزی را مشخص کن.","o":["The controller is a single point of failure, and misconfiguration can affect the whole network","It cannot do segmentation","It forces all devices offline","It requires physical air gaps"],"of":["Controller نقطه‌ی شکست واحد است و Misconfiguration می‌تواند کل شبکه را متأثر کند","نمی‌تواند Segmentation انجام دهد","همه‌ی دستگاه‌ها را آفلاین می‌کند","به Air Gap فیزیکی نیاز دارد"],"en":"If a controller (or its cluster) is compromised, or misconfigured, the entire network can be affected.","fa":"کنترلر نقطه‌ی شکست واحد است؛ هک شدن یا misconfiguration می‌تواند کل شبکه را متأثر کند."},{"id":"secplus:m83","sec":"6","t":"On-prem, SDN & architecture","q":"Which factor is the core priority when designing architecture, according to the lecture?","qf":"طبق درس، کدام عامل اولویت اصلی هنگام طراحی معماری است؟","hf":"در سخنرانی استاد، در طراحی معماری اولویت اصلی گفته شد. ببین کدام: Confidentiality، Cost، Speed یا ...؟","o":["Availability and resilience","Brand colors","The lowest possible license price at any cost","Number of vendors"],"of":["Availability و Resilience (دسترس‌پذیری و تاب‌آوری)","رنگ برند","کمترین قیمت لایسنس به هر قیمتی","تعداد فروشندگان"],"en":"Systems must stay accessible and recover quickly, then balanced with cost, scalability, performance, deployment ease and risk.","fa":"اولویت اول معماری availability و resilience است و بعد با هزینه، مقیاس، کارایی و ریسک متعادل می‌شود."},{"id":"secplus:m84","sec":"6","t":"On-prem, SDN & architecture","q":"Why can cloud designs reduce patching downtime compared to many on-prem designs?","qf":"چرا طراحی‌های Cloud می‌توانند قطعی ناشی از Patch را نسبت به بسیاری از طراحی‌های On-Prem کم کنند؟","hf":"Availability Zones و Region چند مرکز داده‌ی مستقل‌اند. ببین چرا این به کاهش وقفه‌ی پچ کمک می‌کند.","o":["Availability zones and regions allow failover while patches are applied elsewhere","Cloud systems never need patches","Patches are applied by the end user","Maintenance windows are mandatory in cloud"],"of":["Availability Zone و Region اجازه‌ی Failover می‌دهند، در حالی که جای دیگر Patch زده می‌شود","سیستم‌های Cloud هرگز Patch نمی‌خواهند","Patchها توسط کاربر نهایی اعمال می‌شود","Maintenance Window در Cloud اجباری است"],"en":"You can fail over between regions or zones while patching in another, reducing reliance on maintenance windows.","fa":"با availability zone و region می‌شود failover کرد و همزمان patch زد."},{"id":"secplus:m85","sec":"6","t":"ICS/SCADA, RTOS & embedded","q":"What is the top priority of ICS/SCADA systems?","qf":"اولویت اصلی سیستم‌های ICS/SCADA چیست؟","hf":"در سیستم‌های صنعتی (برق، آب، کارخانه) قطع شدن خطرناک‌تر از افشای داده است. ببین اولویت اصلی کدام ضلع CIA است.","o":["Availability (uptime)","Confidentiality of data","Low latency web browsing","Frequent feature updates"],"of":["Availability (دسترس‌پذیری و uptime)","محرمانگی داده","مرور وب با تأخیر کم","آپدیت مکرر قابلیت‌ها"],"en":"Power grids and water plants cannot go down, so availability comes first, even before patching.","fa":"در ICS/SCADA اولویت availability است."},{"id":"secplus:m86","sec":"6","t":"ICS/SCADA, RTOS & embedded","q":"Why are ICS/SCADA systems often vulnerable?","qf":"چرا سیستم‌های ICS/SCADA اغلب آسیب‌پذیرند؟","hf":"ICS/SCADA معمولاً دهه‌ها کار می‌کنند و کمتر به‌روزرسانی می‌شوند. دلیل آسیب‌پذیری‌شان را مشخص کن.","o":["Legacy hardware/software with known vulnerabilities that are hard to patch","They are always connected directly to the cloud","They use too strong encryption","They have too many patches"],"of":["سخت‌افزار/نرم‌افزار قدیمی با آسیب‌پذیری شناخته‌شده که Patch کردنش سخت است","همیشه مستقیم به Cloud وصل‌اند","رمزنگاری بیش از حد قوی دارند","Patch زیادی دارند"],"en":"They run aging systems with little encryption, and patching is limited because of high-availability needs.","fa":"سیستم‌های قدیمی با آسیب‌پذیری شناخته‌شده و patch محدود."},{"id":"secplus:m87","sec":"6","t":"ICS/SCADA, RTOS & embedded","q":"What is the BEST way to protect operational technology (OT) from a compromised IT network?","qf":"بهترین راه محافظت از فناوری عملیاتی (OT) در برابر شبکه‌ی IT آلوده چیست؟","hf":"OT (فناوری عملیاتی) را باید از شبکه‌ی IT جدا کرد تا نفوذ به IT به تجهیزات فیزیکی نرسد. بهترین راه را مشخص کن.","o":["Separate OT from IT (air gap or segmentation) and use firewalls","Place OT servers in the DMZ","Connect OT directly to the internet for patching","Use the same flat network for easier management"],"of":["OT را از IT جدا کنید (Air Gap یا Segmentation) و از فایروال استفاده کنید","سرورهای OT را در DMZ بگذارید","برای Patch مستقیم OT را به اینترنت وصل کنید","برای مدیریت راحت‌تر یک شبکه‌ی تخت (Flat) مشترک بسازید"],"en":"Segmentation limits blast radius so compromise of one side does not give access to the other.","fa":"جداسازی OT از IT شعاع تأثیر حمله را محدود می‌کند."},{"id":"secplus:m88","sec":"6","t":"ICS/SCADA, RTOS & embedded","q":"A real-time operating system (RTOS) is designed for:","qf":"سیستم‌عامل بلادرنگ (RTOS) برای چه ساخته شده است؟","hf":"RTOS سیستم‌عاملی است که پاسخ را در زمان قطعی تضمین می‌کند (مثل ضربان‌ساز یا ترمز خودرو). ببین برای چه طراحی شده.","o":["Tasks with strict timing constraints, such as pacemakers or insulin pumps","General office productivity","Video editing","Cloud bursting"],"of":["کارهایی با قید زمانی سخت، مثل ضربان‌ساز یا پمپ انسولین","بهره‌وری اداری عمومی","ویرایش ویدیو","Cloud Bursting"],"en":"Delays could cause failure or safety risk. These devices are also very hard to patch.","fa":"RTOS برای کارهای با قید زمانی سخت، مثل ضربان‌ساز و پمپ انسولین است و patch آن‌ها دشوار است."},{"id":"secplus:m89","sec":"6","t":"ICS/SCADA, RTOS & embedded","q":"A smart thermostat ships with hard-coded credentials and firmware that cannot be updated. Which category is this?","qf":"یک ترموستات هوشمند با Credential ثابت (Hard-coded) می‌آید و Firmware آن آپدیت نمی‌شود. این چه دسته‌ای است؟","hf":"سیستم‌های Embedded (دستگاه‌های هوشمند) با رمز ثابت و firmware غیرقابل آپدیت. دسته‌ی ریسک را مشخص کن.","o":["Embedded system risk","Serverless risk","SDN controller risk","CDN misconfiguration"],"of":["ریسک سیستم Embedded (توکار)","ریسک Serverless","ریسک Controller در SDN","پیکربندی اشتباه CDN"],"en":"Embedded devices are purpose-built, often with hard-coded credentials/keys and difficult or impossible firmware updates.","fa":"دستگاه embedded معمولاً credential ثابت دارد و firmware آن به‌سختی آپدیت می‌شود."},{"id":"secplus:m90","sec":"6","t":"Segmentation, zones & failure modes","q":"Which describes logical segmentation?","qf":"کدام مورد Segmentation منطقی را توصیف می‌کند؟","hf":"تقسیم‌بندی منطقی یعنی با نرم‌افزار و پیکربندی (VLAN، سابنت، ACL) و نه با کابل و دستگاه فیزیکی جدا. توضیح درست را مشخص کن.","o":["Using VLANs, subnets and ACLs on firewalls to create isolated zones","Unplugging the network cable between buildings","Replacing all switches","Disabling DNS"],"of":["استفاده از VLAN، Subnet و ACL روی فایروال برای ساختن zoneهای ایزوله","کشیدن کابل شبکه بین ساختمان‌ها","تعویض همه‌ی سوئیچ‌ها","غیرفعال کردن DNS"],"en":"Logical segmentation uses VLANs/ACLs. An air gap is physical separation.","fa":"segmentation منطقی با VLAN و ACL انجام می‌شود؛ air gap جداسازی فیزیکی است."},{"id":"secplus:m91","sec":"6","t":"Segmentation, zones & failure modes","q":"Where should a public-facing web server be placed?","qf":"وب‌سرور عمومی (رو به اینترنت) کجا قرار می‌گیرد؟","hf":"سرور عمومی وب باید در منطقه‌ای باشد که حتی اگر هک شود، داخل شبکه‌ی اصلی را نبیند. نام منطقه را مشخص کن.","o":["In the DMZ","In the restricted high-security zone","On the same VLAN as domain controllers","Inside the air-gapped OT network"],"of":["در DMZ","در zone محدود و پرامنیت","روی همان VLAN که Domain Controllerها هستند","داخل شبکه‌ی OT جداشده‌ی فیزیکی (Air-gapped)"],"en":"DMZ hosts are exposed to the internet but isolated from internal systems.","fa":"سرور عمومی در DMZ قرار می‌گیرد و از سیستم‌های داخلی جداست."},{"id":"secplus:m92","sec":"6","t":"Segmentation, zones & failure modes","q":"Which asset belongs in the restricted / high-security zone?","qf":"کدام دارایی در zone محدود / پرامنیت قرار می‌گیرد؟","hf":"منطقه‌ی «محدود/با امنیت بالا» برای حساس‌ترین دارایی‌هاست. ببین کدام دارایی آنجا می‌رود.","o":["Domain controllers and financial databases","Public email gateway","Guest Wi-Fi","Marketing website"],"of":["Domain Controllerها و دیتابیس‌های مالی","گیت‌وی ایمیل عمومی","Wi-Fi مهمان","وب‌سایت بازاریابی"],"en":"Critical assets such as domain controllers, financial databases and IP get the strongest isolation.","fa":"دارایی‌های حیاتی مثل domain controller و دیتابیس مالی در zone محدود می‌روند."},{"id":"secplus:m93","sec":"6","t":"Segmentation, zones & failure modes","q":"Placing assets in the wrong zone mainly results in:","qf":"قرار دادن دارایی در zone اشتباه عمدتاً چه نتیجه‌ای دارد؟","hf":"اگر دارایی‌ها در Zone اشتباه باشند چه می‌شود؟ ببین پیامد را (سطح حمله و حرکت جانبی).","o":["A larger attack surface and easier lateral movement","Faster patching","Lower latency only","No change in risk"],"of":["سطح حمله‌ی بزرگ‌تر و Lateral Movement آسان‌تر","Patch سریع‌تر","فقط تأخیر کمتر","هیچ تغییری در ریسک"],"en":"Misplaced assets break trust boundaries and firewall policy assumptions.","fa":"جای اشتباه دارایی، attack surface و lateral movement را بیشتر می‌کند."},{"id":"secplus:m94","sec":"6","t":"Segmentation, zones & failure modes","q":"A firewall fails and, by design, ALL traffic is blocked. This is:","qf":"یک فایروال خراب می‌شود و طبق طراحی همه‌ی ترافیک مسدود می‌شود. این چیست؟","hf":"Fail-closed یعنی با خرابی، همه‌چیز بسته می‌شود (امن، ولی قطع). Fail-open یعنی با خرابی، باز می‌ماند (در دسترس، ولی ناامن). ببین کدام وضعیت توصیف شده.","o":["Fail-closed","Fail-open","Fail-safe cloud","Load shedding"],"of":["Fail-Closed (با خرابی بسته می‌شود)","Fail-Open (با خرابی باز می‌ماند)","Fail-Safe Cloud","Load Shedding"],"en":"Fail-closed preserves security but can block legitimate users.","fa":"fail-closed یعنی با خرابی همه‌چیز مسدود می‌شود."},{"id":"secplus:m95","sec":"6","t":"Segmentation, zones & failure modes","q":"Which statement about fail-open is correct?","qf":"کدام جمله درباره‌ی Fail-Open درست است؟","hf":"Fail-open: دسترس‌پذیری بالا، اما ریسک ورود غیرمجاز. ببین کدام جمله‌ی درست است.","o":["It maximizes availability but may allow unauthorized access when the control fails","It always blocks traffic","It is the default for every firewall","It eliminates the need for logging"],"of":["Availability را بیشینه می‌کند ولی وقتی کنترل خراب شود ممکن است دسترسی غیرمجاز بدهد","همیشه ترافیک را مسدود می‌کند","پیش‌فرض همه‌ی فایروال‌هاست","نیاز به Logging را از بین می‌برد"],"en":"Fail-open keeps the service up. Use compensating controls and persist logs so traffic can be reviewed later.","fa":"fail-open دسترسی‌پذیری را حفظ می‌کند ولی ممکن است دسترسی غیرمجاز بدهد؛ لاگ و کنترل جبرانی لازم است."},{"id":"secplus:m96","sec":"6","t":"Segmentation, zones & failure modes","q":"A revenue-generating e-commerce site's WAF misbehaves. Compensating controls exist downstream. Which design is MOST defensible?","qf":"WAF یک سایت فروش آنلاین پردرآمد دچار اختلال شده است و کنترل‌های جبرانی پایین‌دست وجود دارد. کدام طراحی قابل‌دفاع‌تر است؟","hf":"سایت درآمدزا نباید با خرابی WAF قطع شود. چون کنترل‌های جبرانی پایین‌دست هست، باید طراحی دفاع‌پذیرتر را پیدا کنی.","o":["Fail-open with detailed logging for later review","Fail-closed with no logs","Disable all controls permanently","Move the site into the restricted zone"],"of":["Fail-Open همراه با Logging دقیق برای بررسی بعدی","Fail-Closed بدون لاگ","غیرفعال کردن دائمی همه‌ی کنترل‌ها","انتقال سایت به zone محدود"],"en":"This is a business-continuity decision. Log traffic during the failure so malicious activity can be reviewed asynchronously.","fa":"برای تداوم کسب‌وکار fail-open با لاگ کامل برای بررسی بعدی."},{"id":"secplus:m97","sec":"6","t":"Segmentation, zones & failure modes","q":"Network (in-line) firewalls are usually deployed in clusters with a heartbeat to:","qf":"فایروال‌های شبکه‌ای (In-Line) معمولاً به‌صورت Cluster با Heartbeat اجرا می‌شوند تا:","hf":"فایروال‌ها خوشه‌ای با ضربان قلب (Heartbeat) نصب می‌شوند. ببین این برای چیست (Failover).","o":["Fail over if one firewall fails so traffic keeps flowing","Increase attack surface","Disable logging","Share user passwords"],"of":["اگر یکی خراب شد Failover شود و ترافیک جریان داشته باشد","سطح حمله بیشتر شود","Logging غیرفعال شود","رمز کاربران به اشتراک گذاشته شود"],"en":"In-line devices are typically fail-closed, so HA clusters avoid an outage.","fa":"firewall in-line معمولاً fail-closed است؛ cluster با heartbeat جلوی قطعی را می‌گیرد."},{"id":"secplus:m98","sec":"6","t":"Firewalls, IDS/IPS & proxies","q":"What is the difference between IDS and IPS?","qf":"تفاوت IDS و IPS چیست؟","hf":"IDS فقط Detective است و IPS Detective + Preventive (در مسیر ترافیک). تفاوت را مشخص کن.","o":["IDS detects and logs; IPS detects and actively blocks in real time","IDS blocks; IPS only logs","Both only log","IPS is only for wireless"],"of":["IDS تشخیص و لاگ می‌کند؛ IPS تشخیص می‌دهد و همان لحظه مسدود هم می‌کند","IDS مسدود می‌کند؛ IPS فقط لاگ می‌کند","هر دو فقط لاگ می‌کنند","IPS فقط برای شبکه‌ی بی‌سیم است"],"en":"IDS is monitor/alert; IPS takes action to block the threat.","fa":"IDS فقط تشخیص و لاگ می‌کند؛ IPS مسدود می‌کند."},{"id":"secplus:m99","sec":"6","t":"Firewalls, IDS/IPS & proxies","q":"What is the main purpose of a load balancer?","qf":"هدف اصلی Load Balancer چیست؟","hf":"Load Balancer ترافیک را بین چند سرور پخش می‌کند. هدف اصلی‌اش را مشخص کن (دسترس‌پذیری، مقیاس‌پذیری).","o":["Distribute traffic across available servers, helping with availability and DDoS resilience","Encrypt disk volumes","Replace DNS","Authenticate users to the domain"],"of":["پخش ترافیک بین سرورهای در دسترس؛ کمک به Availability و مقاومت در برابر DDoS","رمزنگاری دیسک‌ها","جایگزین کردن DNS","احراز هویت کاربران در دامنه"],"en":"It spreads load over healthy back-end servers.","fa":"ترافیک را بین سرورهای سالم پخش می‌کند."},{"id":"secplus:m100","sec":"6","t":"Firewalls, IDS/IPS & proxies","q":"Which services are examples of a CDN?","qf":"کدام سرویس‌ها مثال CDN هستند؟","hf":"CDN = شبکه‌ی توزیع محتوا. نام سرویس‌هایی را مشخص کن که CDN هستند.","o":["Akamai, Cloudflare, CloudFront","Terraform, Ansible, Puppet","Wireshark, Nmap, Burp","IDS, IPS, UTM"],"of":["Akamai، Cloudflare، CloudFront","Terraform، Ansible، Puppet","Wireshark، Nmap، Burp","IDS، IPS، UTM"],"en":"A CDN puts points of presence close to users and absorbs the brunt of traffic.","fa":"CDN نقطه‌ی حضور نزدیک کاربر دارد و فشار ترافیک را می‌گیرد."},{"id":"secplus:m101","sec":"6","t":"Firewalls, IDS/IPS & proxies","q":"A service sits in front of your application, filters inbound traffic and challenges suspected bots. This is a:","qf":"سرویسی جلوی اپلیکیشن شما می‌نشیند، ترافیک ورودی را فیلتر می‌کند و Botهای مشکوک را به چالش می‌کشد. این چیست؟","hf":"سرویسی جلوی برنامه که درخواست‌ها را فیلتر می‌کند، ربات‌ها را چالش می‌دهد و سرور اصلی را پنهان می‌کند. نوع این سرویس را مشخص کن (Forward Proxy برای کلاینت‌هاست و Reverse Proxy برای سرورها).","o":["Reverse proxy","Jump server","Honeypot","SDN controller"],"of":["Reverse Proxy (پراکسی معکوس)","Jump Server","Honeypot","Controller در SDN"],"en":"Reverse proxies (like Cloudflare's model) intermediate, filter and control traffic to the application.","fa":"reverse proxy جلوی اپلیکیشن می‌نشیند، ترافیک را فیلتر می‌کند و bot را به چالش می‌کشد."},{"id":"secplus:m102","sec":"6","t":"Firewalls, IDS/IPS & proxies","q":"What is a jump server used for?","qf":"Jump Server برای چه استفاده می‌شود؟","hf":"Jump Server نقطه‌ی عبور کنترل‌شده برای ادمین‌هاست. کاربردش را مشخص کن.","o":["Securely administering systems in a protected network from a single hardened entry point","Caching web pages","Balancing load","Storing backups"],"of":["مدیریت امن سیستم‌ها در یک شبکه‌ی محافظت‌شده از یک نقطه‌ی ورود سخت‌شده","کش کردن صفحه‌های وب","متعادل‌سازی بار","ذخیره‌ی پشتیبان"],"en":"Admins connect to the jump box first, then to critical servers behind it.","fa":"مدیریت امن سرورها از یک نقطه‌ی ورود سخت‌شده."},{"id":"secplus:m103","sec":"6","t":"Firewalls, IDS/IPS & proxies","q":"Which standard authenticates a device/user before a switch port is enabled and can perform posture checks?","qf":"کدام استاندارد قبل از فعال شدن پورت سوئیچ، دستگاه/کاربر را احراز هویت می‌کند و می‌تواند Posture Check هم انجام دهد؟","hf":"استاندارد کنترل دسترسی پورت: قبل از اینکه دستگاه وصل شود، هویتش را تأیید می‌کند (و می‌تواند وضعیت امنیتی را بسنجد). شماره‌ی استاندارد IEEE را مشخص کن.","o":["802.1X with EAP","SNMPv1","RIP","ARP"],"of":["802.1X با EAP","SNMPv1","RIP","ARP"],"en":"802.1X port-based access control (with EAP) can verify identity and endpoint posture (patch level, AV, managed).","fa":"802.1X با EAP قبل از فعال شدن پورت احراز هویت و posture check انجام می‌دهد."},{"id":"secplus:m104","sec":"6","t":"Firewalls, IDS/IPS & proxies","q":"Port security that limits the number of MAC addresses on a port helps prevent:","qf":"Port Security که تعداد MAC Address روی یک پورت را محدود می‌کند، جلوی چه چیزی را می‌گیرد؟","hf":"Port Security تعداد MAC آدرس مجاز روی پورت سوئیچ را محدود می‌کند. ببین از چه چیزی جلوگیری می‌شود.","o":["Users attaching rogue switches or routers to extend the network","DNS poisoning","SQL injection","Phishing"],"of":["وصل کردن سوئیچ یا روتر غیرمجاز توسط کاربران برای گسترش شبکه","DNS Poisoning","SQL Injection","فیشینگ"],"en":"Exceeding the MAC limit disables the port, preventing unauthorized network extension.","fa":"با عبور از حد MAC پورت غیرفعال می‌شود و جلوی اتصال سوئیچ/روتر غیرمجاز را می‌گیرد."},{"id":"secplus:m105","sec":"6","t":"Firewalls, IDS/IPS & proxies","q":"Which firewall type performs deep packet inspection up to Layer 7?","qf":"کدام نوع فایروال Deep Packet Inspection تا لایه‌ی ۷ انجام می‌دهد؟","hf":"فایروال‌های قدیمی لایه‌ی 3/4 (IP، پورت) را می‌بینند. نوع پیشرفته که تا لایه‌ی 7 (برنامه) را بازرسی می‌کند چیست؟","o":["Next-generation firewall (NGFW)","Traditional packet-filtering firewall","Layer 2 switch","Hub"],"of":["فایروال نسل جدید (NGFW)","فایروال سنتی Packet-Filtering","سوئیچ لایه‌ی ۲","Hub"],"en":"NGFWs filter on application content, beyond IP, port and protocol.","fa":"NGFW با deep packet inspection تا لایه‌ی ۷ می‌رود."},{"id":"secplus:m106","sec":"6","t":"Firewalls, IDS/IPS & proxies","q":"Which product combines firewall, antivirus, IDS/IPS and more in one appliance?","qf":"کدام محصول فایروال، آنتی‌ویروس، IDS/IPS و موارد دیگر را در یک دستگاه ترکیب می‌کند؟","hf":"یک دستگاه همه‌کاره (فایروال، آنتی‌ویروس، IDS/IPS، فیلتر وب) برای شبکه‌های کوچک. نام آن را مشخص کن.","o":["UTM (Unified Threat Management)","WAF","Load balancer","Proxy server only"],"of":["UTM (مدیریت یکپارچه‌ی تهدید)","WAF","Load Balancer","فقط Proxy Server"],"en":"UTM bundles multiple security functions (Sophos and Check Point are examples).","fa":"UTM چند کنترل امنیتی را یک‌جا ترکیب می‌کند."},{"id":"secplus:m107","sec":"6","t":"Firewalls, IDS/IPS & proxies","q":"A zero-day XSS payload is found on your customer login portal. What gives the fastest targeted mitigation?","qf":"یک Payload از نوع XSS Zero-Day روی صفحه‌ی Login مشتریان پیدا شده. چه چیزی سریع‌ترین مهار هدفمند را می‌دهد؟","hf":"آسیب‌پذیری zero-day یعنی هنوز پچی وجود ندارد و باید سریع جلوی همین payload مشخص را بگیری. بین گزینه‌ها دنبال راهی باش که «سریع» و «هدفمند» باشد، نه تغییرات بزرگ و زمان‌بر.","o":["A custom WAF rule blocking that specific payload","Rebooting the web server","Disabling TLS","Adding more load balancers"],"of":["یک قانون سفارشی WAF که همان Payload مشخص را مسدود کند","ری‌استارت وب‌سرور","غیرفعال کردن TLS","اضافه کردن Load Balancer بیشتر"],"en":"WAFs allow granular rules that block a specific malicious payload while the code fix is developed.","fa":"با WAF می‌توان قانون سفارشی برای همان payload نوشت."},{"id":"secplus:m108","sec":"6","t":"Firewalls, IDS/IPS & proxies","q":"The instructor's \"brilliance on the basics\" message means what?","qf":"پیام «Brilliance on the Basics» استاد یعنی چه؟","hf":"سوال درباره‌ی یکی از جمله‌های استاد در کلاس است: «در پایه‌ها درخشان باش». یعنی مفاهیم پایه (API امن، کنترل لایه‌ی 4/7، WAF، DLP) مهم‌تر از ابزارهای پیچیده هستند.","o":["Secure APIs, Layer 4/7 controls, WAF and DLP matter more than AI buzzwords","AI tools replace firewalls","Basic security is unnecessary now","Only cloud controls matter"],"of":["API امن، کنترل‌های لایه‌ی ۴/۷، WAF و DLP از هیاهوی AI مهم‌ترند","ابزارهای AI جای فایروال‌ها را می‌گیرند","امنیت پایه دیگر لازم نیست","فقط کنترل‌های Cloud مهم‌اند"],"en":"AI is a bonus; fundamentals such as API security, firewalls, WAF and data protection are still essential.","fa":"AI بونوس است؛ اصول پایه (امنیت API، firewall، WAF، DLP) همچنان ضروری‌اند."},{"id":"secplus:m109","sec":"6","t":"Secure communications (VPN, SASE)","q":"Which technology is commonly used for site-to-site VPN between a branch and head office?","qf":"کدام فناوری معمولاً برای VPN سایت‌به‌سایت بین شعبه و دفتر مرکزی استفاده می‌شود؟","hf":"VPN شعبه به دفتر مرکزی (Site-to-Site) در لایه‌ی شبکه با تونل رمزنگاری‌شده. نام پروتکل را مشخص کن.","o":["IPsec","HTTP","FTP","Telnet"],"of":["IPsec","HTTP","FTP","Telnet"],"en":"IPsec secures IP traffic at the network layer with authentication and encryption.","fa":"IPsec ترافیک IP را در لایه‌ی شبکه رمزنگاری و احراز هویت می‌کند."},{"id":"secplus:m110","sec":"6","t":"Secure communications (VPN, SASE)","q":"TLS is best described as:","qf":"TLS بهتر از همه چطور توصیف می‌شود؟","hf":"TLS پروتکل رمزنگاری ارتباط لایه‌ی کاربرد است (HTTPS). ببین کدام توصیف درست است.","o":["Encrypting application-layer traffic, commonly seen as HTTPS","A network-layer tunnel for branch offices","A switch port control","A firewall rule language"],"of":["رمزنگاری ترافیک لایه‌ی اپلیکیشن که معمولاً به شکل HTTPS دیده می‌شود","یک تونل لایه‌ی شبکه برای شعبه‌ها","کنترل پورت سوئیچ","یک زبان قانون‌نویسی فایروال"],"en":"TLS protects web and other application traffic in transit.","fa":"TLS ترافیک لایه‌ی اپلیکیشن (مثل HTTPS) را رمزنگاری می‌کند."},{"id":"secplus:m111","sec":"6","t":"Secure communications (VPN, SASE)","q":"What does SD-WAN do?","qf":"SD-WAN چه می‌کند؟","hf":"SD-WAN شبکه‌ی گسترده را با نرم‌افزار مدیریت می‌کند؛ مسیر ترافیک را هوشمند انتخاب می‌کند. ببین کارش چیست.","o":["Intelligently routes application traffic across multiple WAN links to optimize performance, reliability and cost","Replaces the need for encryption","Blocks all inbound traffic","Manages OS patches"],"of":["ترافیک اپلیکیشن را هوشمندانه روی چند لینک WAN مسیریابی می‌کند تا کارایی، پایداری و هزینه بهینه شود","نیاز به رمزنگاری را از بین می‌برد","همه‌ی ترافیک ورودی را مسدود می‌کند","Patchهای OS را مدیریت می‌کند"],"en":"It dynamically selects the best path per application, which also helps latency across clouds and regions.","fa":"SD-WAN مسیر بهینه را برای هر اپلیکیشن انتخاب می‌کند."},{"id":"secplus:m112","sec":"6","t":"Secure communications (VPN, SASE)","q":"SASE combines SD-WAN with which kind of security services?","qf":"SASE، SD-WAN را با چه نوع سرویس امنیتی ترکیب می‌کند؟","hf":"SASE = شبکه + امنیت ابری یکجا. SD-WAN با چه سرویس‌های امنیتی (SWG، CASB، ZTNA) ترکیب می‌شود؟","o":["Cloud-native services such as secure web gateway, CASB, ZTNA and FWaaS","Only antivirus","Physical locks","Backup tapes"],"of":["سرویس‌های Cloud-Native مثل Secure Web Gateway، CASB، ZTNA و FWaaS","فقط آنتی‌ویروس","قفل فیزیکی","نوار پشتیبان"],"en":"SASE delivers networking and security from the cloud with identity-based access.","fa":"SASE شبکه و امنیت cloud-native (SWG، CASB، ZTNA، FWaaS) با دسترسی مبتنی بر هویت است."},{"id":"secplus:m113","sec":"6","t":"Secure communications (VPN, SASE)","q":"In a SaaS-heavy environment (Microsoft 365, Google Workspace), which controls fit best?","qf":"در محیط SaaS-Heavy (مثل Microsoft 365 و Google Workspace) کدام کنترل‌ها بهتر جواب می‌دهند؟","hf":"در Microsoft 365 و Google Workspace داده در ابر است، نه در شبکه‌ی داخلی. ببین کدام کنترل‌ها برای محافظت از ترافیک و داده مناسب‌ترند.","o":["NGFW traffic inspection and data loss prevention (DLP)","Only physical badges","Air gapping all users","Removing all logging"],"of":["بازرسی ترافیک با NGFW و جلوگیری از نشت داده (DLP)","فقط کارت‌های ورود فیزیکی","Air Gap کردن همه‌ی کاربران","حذف همه‌ی Logging"],"en":"SaaS risk is data leakage via SharePoint/Drive. DLP plus inspection address it.","fa":"در محیط SaaS نشت داده مهم است؛ DLP و NGFW مناسب‌اند."},{"id":"secplus:m114","sec":"6","t":"Secure communications (VPN, SASE)","q":"The Security+ exam is described by the instructor as:","qf":"استاد امتحان Security+ را چطور توصیف کرد؟","hf":"آزمون Security+ را استاد چطور توصیف کرد؟ مفهومی، سناریومحور و بدون وابستگی به یک شرکت (Vendor-agnostic).","o":["Vendor-agnostic and concept-focused, with scenario-based performance questions, closed book","Based on specific Cisco CLI commands","Open book","Only multiple choice with no scenarios"],"of":["Vendor-Agnostic و مفهومی، با سؤال‌های سناریویی (Performance-Based) و Closed Book","مبتنی بر دستورهای CLI مخصوص Cisco","Open Book","فقط چندگزینه‌ای بدون سناریو"],"en":"No questions on specific tools. Performance-based questions are scenario-style. The real exam is closed book.","fa":"امتحان vendor-agnostic و مفهومی است، سؤال سناریویی (PBQ) دارد و closed book است."}],"pbq":[{"id":"secplus:p1","sec":"1","t":"Control types","title":"Match each situation to the best control type.","tf":"هر موقعیت را به بهترین نوع کنترل وصل کنید.","zones":["Preventive","Detective","Corrective","Deterrent","Compensating","Directive"],"zf":["Preventive (پیشگیرانه)","Detective (تشخیصی)","Corrective (اصلاحی)","Deterrent (بازدارنده)","Compensating (جبرانی)","Directive (دستوری)"],"items":[["Account lockout after several wrong passwords",0,"قفل شدن حساب بعد از چند رمز اشتباه"],["IDS flags suspicious traffic",1,"IDS ترافیک مشکوک را علامت می‌زند"],["Restoring files from backup after an incident",2,"بازگرداندن فایل‌ها از Backup بعد از حادثه"],["\"Under camera surveillance\" warning sign",3,"تابلوی «تحت نظر دوربین»"],["A guard stands at a door whose badge reader is broken",4,"نگهبانی کنار دری که کارت‌خوانش خراب است"],["Acceptable Use Policy",5,"سیاست استفاده‌ی مجاز (AUP)"]],"zd":[["Stops the incident before it happens","قبل از وقوع جلوی حادثه را می‌گیرد"],["Notices and records that something happened","می‌فهمد و ثبت می‌کند که اتفاقی افتاده"],["Repairs the damage after the incident","بعد از حادثه وضع را درست می‌کند"],["Discourages attackers or bad behavior","مهاجم یا رفتار بد را منصرف می‌کند"],["Temporary or alternative control when the main one fails","کنترل جایگزین وقتی کنترل اصلی کار نمی‌کند"],["A policy or rule that tells people what to do","سیاست یا دستوری که می‌گوید چه کنند"]],"en":"Preventive stops it before it happens, detective notices it, corrective repairs it, deterrent discourages, compensating replaces a failed control, directive tells people what to do.","fa":"Preventive قبل از وقوع جلو می‌گیرد، Detective تشخیص می‌دهد، Corrective اصلاح می‌کند، Deterrent منصرف می‌کند، Compensating جایگزین کنترل خراب است و Directive دستور می‌دهد."},{"id":"secplus:p2","sec":"3","t":"Attack types","title":"Match each scenario to the attack.","tf":"هر سناریو را به حمله‌ی درست وصل کنید.","zones":["Vishing","Smishing","Phishing (email)","Pretexting","Typosquatting","Rogue access point"],"zf":["Vishing (تلفنی)","Smishing (پیامکی)","Phishing (ایمیلی)","Pretexting (داستان‌سازی)","Typosquatting (دامنه‌ی مشابه)","Rogue access point (وای‌فای جعلی)"],"items":[["A phone caller claims to be from the bank and asks for your PIN",0,"تماس‌گیرنده می‌گوید از بانک است و PIN شما را می‌خواهد"],["A text message with a fake delivery link",1,"پیامک با لینک جعلی تحویل مرسوله"],["An email with a fake login page link",2,"ایمیل با لینک صفحه‌ی ورود جعلی"],["Someone invents a believable story (\"I am from IT\") to get information",3,"کسی داستان باورپذیری می‌سازد («از IT هستم») تا اطلاعات بگیرد"],["A look-alike domain such as micros0ft.com",4,"دامنه‌ی شبیه اصلی مثل micros0ft.com"],["A fake Wi-Fi with the company's name",5,"وای‌فای جعلی با نام شرکت"]],"zd":[["Phishing by voice call (phone)","فیشینگ از طریق تماس تلفنی"],["Phishing by SMS text message","فیشینگ از طریق پیامک"],["Fake email with a malicious link","ایمیل جعلی با لینک مخرب"],["Inventing a believable story to get information","ساختن داستان باورپذیر برای گرفتن اطلاعات"],["Registering a look-alike domain","ثبت دامنه‌ای شبیه دامنه‌ی اصلی"],["A fake Wi-Fi network impersonating a real one","وای‌فای جعلی که خود را جای وای‌فای واقعی جا می‌زند"]],"en":"Vishing is voice, smishing is SMS, phishing is email. Pretexting is the made-up story. Typosquatting uses look-alike domains. A rogue AP imitates a Wi-Fi network.","fa":"Vishing تلفنی، Smishing پیامکی، Phishing ایمیلی، Pretexting داستان ساختگی، Typosquatting دامنه‌ی مشابه، Rogue AP وای‌فای جعلی."},{"id":"secplus:p3","sec":"6","t":"Zone placement","title":"Place each asset in the correct security zone.","tf":"هر دارایی را در zone امنیتی درست قرار دهید.","zones":["DMZ","Internal zone","Restricted / high-security zone"],"zf":["DMZ (منطقه‌ی غیرنظامی)","zone داخلی (Internal)","zone محدود / پرامنیت"],"items":[["Public web server",0,"وب‌سرور عمومی"],["Public email gateway",0,"گیت‌وی ایمیل عمومی"],["Employee workstation",1,"ایستگاه کار کارمند"],["Internal file share",1,"File Share داخلی"],["Domain controller",2,"Domain Controller"],["Financial database",2,"دیتابیس مالی"]],"zd":[["Public-facing servers, isolated from the internal network","سرورهای رو به اینترنت، جدا از شبکه‌ی داخلی"],["Trusted corporate resources: workstations, file shares, internal apps","منابع معمولی شرکت: ایستگاه کار، File Share، اپ‌های داخلی"],["Crown-jewel assets: domain controllers, financial databases","دارایی‌های حیاتی: Domain Controller و دیتابیس مالی"]],"en":"Public-facing hosts go in the DMZ. Trusted corporate resources are internal. Crown-jewel assets such as domain controllers and financial databases get the restricted zone.","fa":"میزبان‌های عمومی در DMZ، منابع معمولی شرکت در zone داخلی و دارایی‌های حیاتی (domain controller و دیتابیس مالی) در zone محدود."},{"id":"secplus:p4","sec":"6","t":"Failure mode","title":"Choose the best failure mode for each system.","tf":"برای هر سیستم بهترین حالت خرابی را انتخاب کنید.","zones":["Fail-open","Fail-closed"],"zf":["Fail-open (با خرابی باز می‌ماند)","Fail-closed (با خرابی بسته می‌شود)"],"items":[["An in-line perimeter firewall protecting a bank's internal network (no HA cluster)",1,"فایروال محیطی In-Line که شبکه‌ی داخلی یک بانک را محافظت می‌کند (بدون HA Cluster)"],["A WAF in front of a revenue-generating e-commerce checkout, with strong compensating controls downstream and full logging",0,"یک WAF جلوی صفحه‌ی پرداخت یک فروشگاه آنلاین پردرآمد، با کنترل‌های جبرانی قوی پایین‌دست و Logging کامل"],["A door lock on a restricted data-center room that holds crown-jewel servers",1,"قفل درِ اتاق محدود دیتاسنتر که سرورهای بسیار حیاتی در آن است"],["A DDoS-scrubbing filter whose failure would take a public news site offline",0,"فیلتر پاک‌سازی DDoS که خرابی‌اش یک سایت خبری عمومی را آفلاین می‌کند"]],"zd":[["Stays available when the control fails; needs compensating controls and logs","وقتی کنترل خراب شود سیستم در دسترس می‌ماند؛ به کنترل جبرانی و لاگ نیاز دارد"],["Blocks everything when the control fails; protects security but may block legitimate users","با خرابی همه‌چیز را مسدود می‌کند؛ امنیت حفظ می‌شود ولی کاربر قانونی هم بلاک می‌شود"]],"en":"Choose fail-closed where unauthorized access costs more than downtime. Choose fail-open where availability is critical and compensating controls and logs exist.","fa":"جایی که دسترسی غیرمجاز بدتر از قطعی است fail-closed؛ جایی که availability حیاتی است و کنترل جبرانی و لاگ وجود دارد fail-open."},{"id":"secplus:p5","sec":"6","t":"Match the technology","title":"Match each description to the correct technology.","tf":"هر توضیح را به فناوری درست وصل کنید.","zones":["IDS","IPS","WAF","UTM","NGFW","Reverse proxy"],"zf":["IDS (تشخیص نفوذ)","IPS (پیشگیری از نفوذ)","WAF (فایروال وب‌اپ)","UTM (مدیریت یکپارچه‌ی تهدید)","NGFW (فایروال نسل جدید)","Reverse proxy (پراکسی معکوس)"],"items":[["Monitors and logs suspicious activity but takes no action",0,"فعالیت مشکوک را پایش و لاگ می‌کند ولی اقدامی نمی‌کند"],["Blocks detected threats in real time",1,"تهدیدهای تشخیص‌داده‌شده را همان لحظه مسدود می‌کند"],["Filters HTTP traffic and can block a specific XSS payload",2,"ترافیک HTTP را فیلتر می‌کند و می‌تواند یک Payload مشخص XSS را مسدود کند"],["Firewall, antivirus and IDS/IPS in one appliance",3,"فایروال، آنتی‌ویروس و IDS/IPS در یک دستگاه"],["Deep packet inspection up to Layer 7",4,"بازرسی عمیق بسته تا لایه‌ی ۷"],["Sits in front of apps, filters inbound traffic and challenges bots",5,"جلوی اپلیکیشن می‌نشیند، ترافیک ورودی را فیلتر می‌کند و Botها را به چالش می‌کشد"]],"zd":[["Detects and logs only","فقط تشخیص و لاگ"],["Detects and blocks in real time","تشخیص و مسدودسازی لحظه‌ای"],["Filters web (HTTP) traffic; custom rules for web attacks such as XSS","فیلتر ترافیک وب و قانون سفارشی برای حمله‌های وب مثل XSS"],["Firewall + antivirus + IDS/IPS in one box","فایروال + آنتی‌ویروس + IDS/IPS در یک دستگاه"],["Deep packet inspection up to Layer 7","بازرسی عمیق بسته تا لایه‌ی ۷"],["Sits in front of apps, filters inbound traffic, challenges bots","جلوی اپلیکیشن می‌نشیند، ترافیک ورودی را فیلتر و Bot را به چالش می‌کشد"]],"en":"IDS detects; IPS blocks; WAF protects web apps; UTM bundles functions; NGFW inspects up to Layer 7; a reverse proxy fronts the application.","fa":"IDS تشخیص، IPS مسدودسازی، WAF محافظ وب، UTM ترکیب چند کنترل، NGFW بازرسی لایه‌ی ۷، reverse proxy جلوی اپلیکیشن."},{"id":"secplus:p6","sec":"6","t":"Secure communications","title":"Pick the best technology for each need.","tf":"برای هر نیاز بهترین فناوری را انتخاب کنید.","zones":["IPsec","TLS","SD-WAN","SASE","Direct Connect","Jump server"],"zf":["IPsec","TLS","SD-WAN","SASE","Direct Connect (اتصال اختصاصی)","Jump server (سرور پرش)"],"items":[["Branch office to head office encrypted tunnel",0,"تونل رمزنگاری‌شده بین شعبه و دفتر مرکزی"],["Protect web traffic between browser and server (HTTPS)",1,"محافظت از ترافیک وب بین مرورگر و سرور (HTTPS)"],["Optimize routing across multiple internet links for cost and latency",2,"بهینه‌کردن مسیریابی روی چند لینک اینترنت برای هزینه و تأخیر"],["Identity-based, cloud-delivered networking plus security (SWG, CASB, ZTNA)",3,"شبکه + امنیت مبتنی بر هویت و تحویل‌شده از Cloud (SWG، CASB، ZTNA)"],["Dedicated private link from on-prem to a cloud provider",4,"لینک خصوصی اختصاصی از On-Prem به ارائه‌دهنده‌ی Cloud"],["Single hardened entry point to administer critical servers",5,"یک نقطه‌ی ورود سخت‌شده برای مدیریت سرورهای حیاتی"]],"zd":[["Network-layer encrypted tunnel, typical for site-to-site VPN","تونل رمزنگاری‌شده در لایه‌ی شبکه، رایج برای Site-to-Site VPN"],["Encrypts application traffic, i.e. HTTPS","رمزنگاری ترافیک اپلیکیشن، یعنی HTTPS"],["Smart routing across multiple WAN links for performance and cost","مسیریابی هوشمند روی چند لینک WAN برای کارایی و هزینه"],["SD-WAN + cloud-delivered security (SWG, CASB, ZTNA, FWaaS), identity-based","SD-WAN + امنیت cloud (SWG، CASB، ZTNA، FWaaS) مبتنی بر هویت"],["Dedicated private link from on-prem to the cloud","لینک اختصاصی خصوصی از On-Prem به Cloud"],["Single hardened entry point for admin access","نقطه‌ی ورود سخت‌شده برای مدیریت سرورها"]],"en":"IPsec for site-to-site, TLS for HTTPS, SD-WAN for path selection, SASE for cloud-delivered network security, Direct Connect for dedicated links, jump server for admin access.","fa":"IPsec برای site-to-site، TLS برای HTTPS، SD-WAN برای انتخاب مسیر، SASE برای شبکه+امنیت cloud، Direct Connect برای لینک اختصاصی، jump server برای مدیریت."}]});
